```rust
pub struct KeyList {
    data: Vec<(String, i32)>,
}

impl KeyList {
    pub fn new() -> KeyList {
        KeyList { data: Vec::new() }
    }

    pub fn insert(&mut self, key: String, value: i32) {
        if let Some((_, v)) = self.data.iter_mut().find(|(k, _)| k == &key) {
            *v = value;
        } else {
            self.data.push((key, value));
        }
    }

    pub fn remove(&mut self, key: &str) {
        if let Some(index) = self.data.iter().position(|(k, _)| k == key) {
            self.data.remove(index);
        }
    }

    pub fn get(&self, key: &str) -> Option<&i32> {
        self.data.iter().find_map(|(k, v)| if k == key { Some(v) } else { None })
    }

    pub fn iter(&self) -> impl Iterator<Item = (&String, &i32)> {
        self.data.iter().map(|(k, v)| (k, v))
    }
}

fn main() {
    let mut key_list = KeyList::new();
    key_list.insert("apple".to_string(), 5);
    key_list.insert("banana".to_string(), 3);
    key_list.insert("apple".to_string(), 7);

    for (key, value) in key_list.iter() {
        println!("{}: {}", key, value);
    }

    key_list.remove("banana");

    match key_list.get("apple") {
        Some(value) => println!("Value of apple: {}", value),
        None => println!("Key 'apple' not found"),
    }
}
```

