```rust
use itertools::Itertools;

struct File {
    tags: Vec<String>,
    layers: Vec<String>,
}

fn process_files(files: &[File]) -> (Vec<String>, Vec<String>) {
    let tags = files
        .iter()
        .flat_map(|f| f.tags.iter().cloned())
        .sorted()
        .dedup()
        .collect::<Vec<_>>();
    let layers = files
        .iter()
        .flat_map(|f| f.layers.iter().cloned())
        .sorted()
        .dedup()
        .collect::<Vec<_>>();
    (tags, layers)
}

fn main() {
    let files = vec![
        File {
            tags: vec!["rust".to_string(), "programming".to_string()],
            layers: vec!["frontend".to_string(), "backend".to_string()],
        },
        File {
            tags: vec!["programming".to_string(), "coding".to_string()],
            layers: vec!["frontend".to_string(), "testing".to_string()],
        },
        File {
            tags: vec!["rust".to_string(), "coding".to_string()],
            layers: vec!["backend".to_string(), "testing".to_string()],
        },
    ];
    let (unique_tags, unique_layers) = process_files(&files);
    println!("{:?}", unique_tags);
    println!("{:?}", unique_layers);
}
```

The `process_files` function iterates through the collection of files, flattens the tags and layers, sorts them in lexicographical order, removes duplicates, and collects the unique tags and layers into vectors. The main function demonstrates the usage of the `process_files` function with a sample input and prints the unique tags and layers.

