```rust
use std::sync::mpsc;

#[derive(Debug)]
enum Events {
    GunFired,
    SoundPlayed,
}

struct EventProcessor {
    gun_fired_event: mpsc::Receiver<Events>,
    event_sender: mpsc::Sender<Events>,
}

impl EventProcessor {
    fn process_events(&self) -> Result<(), mpsc::SendError<Events>> {
        let gun_fired = if let Ok(event) = self.gun_fired_event.try_recv() {
            event
        } else {
            return Ok(());
        };

        // play the sound
        dbg!(gun_fired);

        self.event_sender.send(Events::SoundPlayed)?;

        Ok(())
    }
}
