struct Rgba(u8, u8, u8, u8);

fn avg_colour(rgba_data: &[u8]) -> Rgba {
    let mut avg = [0f64; 4];
    let mut count = 0;

    for p in rgba_data.chunks(4) {
        avg[0] += (p[0] as u64 * p[0] as u64) as f64; // Sum of squares of red values
        avg[1] += (p[1] as u64 * p[1] as u64) as f64; // Sum of squares of green values
        avg[2] += (p[2] as u64 * p[2] as u64) as f64; // Sum of squares of blue values
        avg[3] += p[3] as f64; // Sum of alpha values
        count += 1;
    }

    let total_pixels = count as f64;
    let avg_red = (avg[0] / total_pixels).sqrt() as u8; // Calculate average red value
    let avg_green = (avg[1] / total_pixels).sqrt() as u8; // Calculate average green value
    let avg_blue = (avg[2] / total_pixels).sqrt() as u8; // Calculate average blue value
    let avg_alpha = (avg[3] / total_pixels) as u8; // Calculate average alpha value

    Rgba(avg_red, avg_green, avg_blue, avg_alpha)
}

