use std::io;

fn guessing_game(range: RangeInclusive<u32>) -> u32 {
    let secret_number = rand::random::<u32>() % (range.end() - range.start() + 1) + range.start();
    let mut num_guesses = 0;

    loop {
        println!("Please guess a number between {} and {}: ", range.start(), range.end());
        let mut guess = String::new();
        io::stdin().read_line(&mut guess).expect("Failed to read line");
        let guess: u32 = match guess.trim().parse() {
            Ok(num) => num,
            Err(_) => {
                println!("Please enter a valid number!");
                continue;
            }
        };

        num_guesses += 1;

        match guess.cmp(&secret_number) {
            std::cmp::Ordering::Less => println!("Too small!"),
            std::cmp::Ordering::Greater => println!("Too big!"),
            std::cmp::Ordering::Equal => {
                println!("You win! It took you {} guesses.", num_guesses);
                break;
            }
        }
    }

    num_guesses
}
