use std::sync::mpsc;
use std::thread;

// Define a struct representing the message sender
struct MessageSender {
    sender: mpsc::Sender<String>,
}

impl MessageSender {
    // Method to send a message to the receiver
    fn send(&self, message: &str) {
        self.sender.send(String::from(message)).unwrap();
    }

    // Method to clone the sender
    fn clone_sender(&self) -> MessageSender {
        MessageSender {
            sender: self.sender.clone(),
        }
    }
}

// Define a struct representing the message receiver
struct MessageReceiver {
    receiver: mpsc::Receiver<String>,
}

impl MessageReceiver {
    // Method to clone the receiver
    fn clone_receiver(&self) -> MessageReceiver {
        MessageReceiver {
            receiver: self.receiver.clone(),
        }
    }

    // Method to receive messages
    fn receive(&self) -> String {
        self.receiver.recv().unwrap()
    }
}

fn main() {
    // Create a channel for communication between sender and receiver
    let (sender, receiver) = mpsc::channel();

    // Create a sender and receiver
    let message_sender = MessageSender { sender };
    let message_receiver = MessageReceiver { receiver };

    // Clone the sender and receiver
    let cloned_sender = message_sender.clone_sender();
    let cloned_receiver = message_receiver.clone_receiver();

    // Send a message from the original sender to the original receiver
    message_sender.send("Hello, receiver!");

    // Receive and print the message from the original receiver
    println!("Original Receiver: {}", message_receiver.receive());

    // Send a message from the cloned sender to the cloned receiver
    cloned_sender.send("Hello, cloned receiver!");

    // Receive and print the message from the cloned receiver
    println!("Cloned Receiver: {}", cloned_receiver.receive());
}
```

