fn hamming_distance(strand1: &str, strand2: &str) -> Option<usize> {
    if strand1.len() != strand2.len() {
        return None;
    }

    Some(strand1.chars().zip(strand2.chars()).filter(|(c1, c2)| c1 != c2).count())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_no_difference_between_empty_strands() {
        assert_eq!(hamming_distance("", ""), Some(0));
    }

    #[test]
    fn test_no_difference_between_identical_strands() {
        assert_eq!(hamming_distance("GGACTGA", "GGACTGA"), Some(0));
    }

    #[test]
    fn test_complete_hamming_distance_in_small_strand() {
        assert_eq!(hamming_distance("ACT", "GGA"), Some(3));
    }

    #[test]
    fn test_hamming_distance_for_large_strand() {
        assert_eq!(hamming_distance("GAGCCTACTAACGGGAT", "CATCGTAATGACGGCCT"), Some(7));
    }

    #[test]
    fn test_handles_different_length_strands() {
        assert_eq!(hamming_distance("AGT", "AGTC"), None);
    }
}
```

The `hamming_distance` function first checks if the input strands have different lengths and returns `None` if they do. Otherwise, it zips the characters of the two strands together, filters the pairs where the characters are different, and counts the differences to obtain the Hamming distance. The provided test cases ensure the correctness of the implementation.

