use nix::mount;
use nix::mount::MsFlags;
use nix::Error;
use std::fs;
use std::path::Path;

fn mount_directory(source: &str, dest: &str, readonly: bool) -> Result<(), String> {
    let dest_path = Path::new(dest);
    if dest_path.exists() {
        let cloned_dest = dest_path.with_file_name(format!("{}_clone", dest_path.file_name().unwrap().to_str().unwrap()));
        match fs::create_dir(&cloned_dest) {
            Ok(_) => {
                match mount::mount(Some(source), &cloned_dest, None::<&str>, MsFlags::MS_BIND, None) {
                    Ok(_) => {
                        let mut flags = MsFlags::MS_BIND;
                        if readonly {
                            flags |= MsFlags::MS_RDONLY;
                        }
                        match mount::mount(None::<&str>, &cloned_dest, None::<&str>, flags, None) {
                            Ok(_) => Ok(()),
                            Err(e) => Err(format!("Failed to perform mount operation: {}", e)),
                        }
                    }
                    Err(e) => Err(format!("Failed to clone destination directory: {}", e)),
                }
            }
            Err(e) => Err(format!("Failed to create cloned destination directory: {}", e)),
        }
    } else {
        Err(String::from("Destination directory does not exist"))
    }
}
