fn process_mp3_frame(frame: &[u8]) -> Option<(u32, u32)> {
    if frame.len() < 4 {
        return None;
    }

    let frame_sync = (frame[0] as u16) << 4 | (frame[1] as u16 >> 4);
    let mpeg_version = (frame[1] >> 3) & 0b11;
    let layer = (frame[1] >> 1) & 0b11;
    let protection = frame[1] & 0b1;
    let bitrate_index = (frame[2] >> 4) & 0b1111;
    let sample_rate_index = (frame[2] >> 2) & 0b11;

    let sample_rate = match mpeg_version {
        0b00 => match sample_rate_index {
            0b00 => 11025,
            0b01 => 12000,
            0b10 => 8000,
            _ => return None,
        },
        0b01 => match sample_rate_index {
            0b00 => 22050,
            0b01 => 24000,
            0b10 => 16000,
            _ => return None,
        },
        0b10 => match sample_rate_index {
            0b00 => 44100,
            0b01 => 48000,
            0b10 => 32000,
            _ => return None,
        },
        _ => return None,
    };

    let bitrate = match (mpeg_version, layer, bitrate_index) {
        (0b01, 0b11, _) => return None, // Reserved
        (_, _, 0b0000) => return None, // Free
        (_, _, 0b1111) => return None, // Bad
        (0b11, 0b01, _) => return None, // Layer I
        (0b11, 0b10, _) => return None, // Layer II
        (0b11, 0b11, _) => return None, // Layer III
        (_, _, _) => {
            let bitrates = [
                [0, 32, 64, 96, 128, 160, 192, 224, 256, 288, 320, 352, 384, 416, 448],
                [0, 32, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384],
                [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320],
            ];
            bitrates[mpeg_version as usize - 1][(bitrate_index - 1) as usize]
        }
    };

    Some((sample_rate, bitrate))
}
```

