        pub user_id: String,

        /// The ID of the device for which the keys are being requested.
        pub device_id: String,
    }
}

// Implementing Serialize and Deserialize for KeyRequestEvent
impl Serialize for KeyRequestEvent {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        let mut state = serializer.serialize_struct("KeyRequestEvent", 3)?;
        state.serialize_field("request_id", &self.request_id)?;
        state.serialize_field("user_id", &self.user_id)?;
        state.serialize_field("device_id", &self.device_id)?;
        state.end()
    }
}

impl<'de> Deserialize<'de> for KeyRequestEvent {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        struct KeyRequestEventVisitor;

        impl<'de> serde::de::Visitor<'de> for KeyRequestEventVisitor {
            type Value = KeyRequestEvent;

            fn expecting(&self, formatter: &mut std::fmt::Formatter) -> std::fmt::Result {
                formatter.write_str("struct KeyRequestEvent")
            }

            fn visit_map<A>(self, mut map: A) -> Result<Self::Value, A::Error>
            where
                A: serde::de::MapAccess<'de>,
            {
                let mut request_id = None;
                let mut user_id = None;
                let mut device_id = None;

                while let Some(key) = map.next_key()? {
                    match key {
                        "request_id" => {
                            request_id = Some(map.next_value()?);
                        }
                        "user_id" => {
                            user_id = Some(map.next_value()?);
                        }
                        "device_id" => {
                            device_id = Some(map.next_value()?);
                        }
                        _ => {
                            let _: serde::de::IgnoredAny = map.next_value()?;
                        }
                    }
                }

                let request_id = request_id.ok_or_else(|| serde::de::Error::missing_field("request_id"))?;
                let user_id = user_id.ok_or_else(|| serde::de::Error::missing_field("user_id"))?;
                let device_id = device_id.ok_or_else(|| serde::de::Error::missing_field("device_id"))?;

                Ok(KeyRequestEvent { request_id, user_id, device_id })
            }
        }

        deserializer.deserialize_struct("KeyRequestEvent", &["request_id", "user_id", "device_id"], KeyRequestEventVisitor)
