use proc_macro2::TokenStream as TokenStream2;
use quote::quote;
use syn::{parse::Result, parse_quote, DeriveInput};

#[proc_macro]
pub fn impl_wrapper(input: TokenStream) -> TokenStream {
    let input = parse_macro_input!(input as DeriveInput);
    let struct_name = &input.ident;
    let fields = if let syn::Data::Struct(syn::DataStruct { fields, .. }) = &input.data {
        fields
    } else {
        panic!("This macro only supports structs");
    };

    let field_names = fields.iter().map(|field| {
        if let Some(ident) = &field.ident {
            ident
        } else {
            panic!("This macro does not support tuple or unit structs");
        }
    });

    let field_types = fields.iter().map(|field| &field.ty);

    let gen = quote! {
        impl MyTrait for #struct_name {
            fn my_method(&self) -> String {
                self.inner.my_method()
            }
        }

        pub struct #struct_name Wrapper {
            inner: #struct_name,
        }

        impl #struct_name Wrapper {
            pub fn new(inner: #struct_name) -> Self {
                #struct_name Wrapper { inner }
            }
        }
    };

    gen.into()
}
