use par_trie::ParTrie;

const WORDS: &[&str; 20] = &[
    "the", "them", "code", "coder", "coding",
    "crap", "help", "heft", "apple", "hello",
    // Additional words can be added here
];

fn autocomplete(prefix: &str) -> Vec<String> {
    let trie = ParTrie::new();
    for word in WORDS {
        trie.insert(word.to_string(), ());
    }

    let mut completions = Vec::new();
    let mut current_node = &trie;
    for c in prefix.chars() {
        if let Some(next_node) = current_node.get_child(&c) {
            current_node = next_node;
        } else {
            return completions;
        }
    }

    trie.traverse_from(current_node, prefix, &mut completions);
    completions
}

fn main() {
    let prefix = "he";
    let completions = autocomplete(prefix);
    println!("Autocomplete suggestions for '{}': {:?}", prefix, completions);
}
