use std::collections::{HashSet, HashMap};

struct Package {
    name: String,
    dependencies: HashSet<String>,
}

impl Package {
    fn new(name: &str, dependencies: HashSet<String>) -> Self {
        Package {
            name: name.to_string(),
            dependencies,
        }
    }
}

fn resolve_dependencies(packages: Vec<Package>) -> Result<(), String> {
    let mut dependency_map: HashMap<String, HashSet<String>> = HashMap::new();

    for package in &packages {
        dependency_map.insert(package.name.clone(), package.dependencies.clone());
    }

    for package in &packages {
        for dependency in &package.dependencies {
            if !dependency_map.contains_key(dependency) {
                return Err(format!("Unexpected dependency: {}", dependency));
            }
        }
    }

    Ok(())
}
```

The `resolve_dependencies` function creates a map of package names to their dependencies and then iterates through each package to check for unexpected dependencies. If an unexpected dependency is found, it returns an error with the message indicating the unexpected dependency. Otherwise, it returns `Ok(())` to indicate that all dependencies are resolved successfully.

