use std::fmt;
use std::borrow::Borrow;

struct NamePart<'a>(&'a str);
struct Argument<'a>(&'a str);

struct Command<N, A> {
    name: N,
    query: Option<String>,
    arguments: A,
}

impl<'a, N, A> fmt::Display for Command<N, A>
where
    N: Borrow<[NamePart<'a>]>,
    A: Borrow<[Argument<'a>]>,

{
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.name.borrow().iter().map(|part| part.0).collect::<Vec<_>>().join(" "))?;
        if let Some(query) = &self.query {
            write!(f, " {}", query)?;
        }
        for arg in self.arguments.borrow().iter() {
            write!(f, " {}", arg.0)?;
        }
        Ok(())
    }
}

fn main() {
    let name_parts = vec![NamePart("git"), NamePart("commit")];
    let arguments = vec![Argument("-m"), Argument("Initial commit")];
    let command = Command {
        name: &name_parts[..],
        query: None,
        arguments: &arguments[..],
    };
    println!("{}", command); // Output: git commit -m Initial commit
}
```

In the solution, the `fmt::Display` trait is implemented for the `Command` structure. The implementation uses the `Borrow` trait to access the borrowed slices of `NamePart` and `Argument`. The `fmt` method formats the command by concatenating the name parts, query (if present), and arguments into a single string. When the `main` function is executed, it creates a `Command` instance and prints the formatted command string.

