pub fn polymer(&self, polymer: &String) -> Option<f32> {
    let seq = polymer.to_ascii_uppercase();

    let len = seq.len();
    if len < 3 {
        return None;
    }

    let nuc = ['A', 'G', 'C', 'T'];
    if !seq.chars().all(|c| nuc.contains(&c)) {
        return None;
    }

    let gc_count = seq.chars().filter(|&c| c == 'G' || c == 'C').count() as f32;
    Some(gc_count / len as f32)
}
```

