    fn new(name: String, price: f64, quantity: i32) -> Item {
        Item { name, price, quantity }
    }
}

fn add_item(inventory: &mut Vec<Item>, name: String, price: f64, quantity: i32) {
    let item = Item::new(name, price, quantity);
    inventory.push(item);
}

fn remove_item(inventory: &mut Vec<Item>, name: &str) {
    inventory.retain(|item| item.name != name);
}

fn update_quantity(inventory: &mut Vec<Item>, name: &str, new_quantity: i32) {
    if let Some(item) = inventory.iter_mut().find(|item| item.name == name) {
        item.quantity = new_quantity;
    }
}

fn display_inventory(inventory: &Vec<Item>) {
    for item in inventory {
        println!("Name: {}, Price: ${}, Quantity: {}", item.name, item.price, item.quantity);
    }
}

fn calculate_inventory_value(inventory: &Vec<Item>) -> f64 {
    inventory.iter().map(|item| item.price * item.quantity as f64).sum()
}

fn main() {
    let mut inventory: Vec<Item> = Vec::new();

    add_item(&mut inventory, String::from("Apple"), 1.5, 10);
    add_item(&mut inventory, String::from("Banana"), 0.75, 20);
