use std::ptr;

struct DeferStack<'a> {
    inner: std::cell::Cell<*mut Vec<Box<dyn FnOnce() + 'a>>>,
}

impl<'a> DeferStack<'a> {
    fn new() -> DeferStack<'a> {
        DeferStack {
            inner: std::cell::Cell::new(ptr::null_mut()),
        }
    }

    fn defer<F: FnOnce() + 'a>(&self, f: F) {
        unsafe {
            let v: &mut Vec<_> = &mut *self.inner.get();
            v.push(Box::new(f));
        }
    }
}

impl<'a> Drop for DeferStack<'a> {
