use std::ptr;

struct DeferStack<'a> {
    inner: std::cell::Cell<*mut Vec<Box<dyn FnOnce() + 'a>>>,
}

impl<'a> DeferStack<'a> {
    fn new() -> DeferStack<'a> {
        DeferStack {
            inner: std::cell::Cell::new(Box::into_raw(Box::new(Vec::new()))),
        }
    }

    fn defer<F: FnOnce() + 'a>(&self, f: F) {
        unsafe {
            let v: &mut Vec<_> = &mut *self.inner.get();
            v.push(Box::new(f));
        }
    }

    fn run_deferred(&self) {
        unsafe {
            let v: *mut Vec<Box<dyn FnOnce() + 'a>> = self.inner.get();
            let mut v = Box::from_raw(v);

            while let Some(defer) = v.pop() {
                defer();
            }
        }
    }
}

fn main() {
    let defer_stack = DeferStack::new();

    defer_stack.defer(|| println!("Deferred action 1"));
    defer_stack.defer(|| println!("Deferred action 2"));

    // At this point, all deferred actions should be executed in reverse order
    defer_stack.run_deferred();
}
```

