fn filter_repositories(repositories: &[(String, i32)], star_range: (i32, i32)) -> Vec<String> {
    repositories
        .iter()
        .filter(|(_, stars)| *stars >= star_range.0 && *stars <= star_range.1)
        .map(|(name, _)| name.clone())
        .collect()
}

fn extract_module(module_path: &str) -> String {
    let parts: Vec<&str> = module_path.split("::").collect();
    parts.last().unwrap_or(&"").trim().trim_end_matches(';').trim()
        .split_whitespace().next().unwrap_or(&"").trim_end_matches(';').trim().to_string()
}
```

