use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::HashSet;

fn extract_gene_names(file_path: &str) -> Result<Vec<String>, std::io::Error> {
    let file = File::open(file_path)?;
    let reader = BufReader::new(file);
    let mut gene_names = HashSet::new();

    for line in reader.lines() {
        let line = line?;
        let fields: Vec<&str> = line.split('\t').collect();
        if let Some(attributes) = fields.get(8) {
            for attribute in attributes.split(';') {
                if let Some(key_value) = attribute.split_once(' ') {
                    if key_value.0.trim() == "gene_name" {
                        if let Some(gene_name) = key_value.1.trim().trim_matches('"').split_once('"') {
                            gene_names.insert(gene_name.0.to_string());
                        }
                    }
                }
            }
        }
    }

    Ok(gene_names.into_iter().collect())
}
