use actix_web::{web, HttpResponse, Result};
use serde::Deserialize;
use std::sync::{Arc, Mutex};

// Define the application state containing the counters
struct AppState {
    counters: Arc<Mutex<Vec<Counter>>>,
}

// Define the structure for the counter
struct Counter {
    id: u32,
    value: u32,
}

// Define the JSON structure for the value by which the counter should be incremented
#[derive(Deserialize)]
struct JsonBodyChangeBy {
    value: u32,
}

// Define the JSON structure for the result containing the updated counter value
#[derive(Serialize)]
struct JsonResult {
    data: CounterDto,
}

// Define the JSON structure for the counter data to be returned
#[derive(Serialize)]
struct CounterDto {
    counter: u32,
}

// Handler function for the endpoint /counters/{counter_id}/increment
async fn increment(
    data: web::Data<AppState>,
    web::Path(counter_id): web::Path<u32>,
    value: web::Json<JsonBodyChangeBy>,
) -> Result<HttpResponse> {
    // Retrieve the counter with the specified counter_id
    let mut counters = data.counters.lock().unwrap();
    if let Some(counter) = counters.iter_mut().find(|c| c.id == counter_id) {
        // Increment the counter by the value specified in the JSON object
        counter.value += value.value;
        // Return an HTTP response with the updated counter value in JSON format
        Ok(HttpResponse::Ok().json(JsonResult {
            data: CounterDto {
