fn process_packet(packets: Vec<Packet>) -> Vec<(u64, String)> {
    packets
        .into_iter()
        .map(|packet| {
            let processed_data = match packet.data {
                PacketData::Text(text) => (packet.id, text.to_uppercase().into_owned()),
                PacketData::Binary(binary) => {
                    let sum: u8 = binary.iter().sum();
                    (packet.id, sum.to_string())
                }
            };
            processed_data
        })
        .collect()
}
