use std::collections::HashSet;

#[derive(Debug, PartialEq)]
enum TokenSimilarity {
    Identical,
    SameLetters,
    Distant,
}

fn http_token(token: &str) -> String {
    token.to_string()
}

fn determine_similarity(token1: &str, token2: &str) -> TokenSimilarity {
    let set1: HashSet<char> = token1.chars().filter(|c| c.is_alphabetic()).collect();
    let set2: HashSet<char> = token2.chars().filter(|c| c.is_alphabetic()).collect();

    if set1 == set2 {
        TokenSimilarity::Identical
    } else if token1.chars().all(|c| !c.is_alphabetic()) && token2.chars().all(|c| !c.is_alphabetic()) {
        TokenSimilarity::Identical
    } else {
        TokenSimilarity::Distant
    }
}

fn main() {
    assert_eq!(determine_similarity(&http_token("token"), &http_token("Token\t")), TokenSimilarity::SameLetters);
    assert_eq!(determine_similarity(&http_token("same-token"), &http_token("Same\t-Token")), TokenSimilarity::SameLetters);
}
```

