        vec![0, 3, 4],
        vec![0, 5],
        vec![1],
        vec![1],
        vec![2],
    ];
    let start_node = 0;
    let result = bfs_traversal(&graph, start_node);
    println!("BFS Traversal Order: {:?}", result); // Output: BFS Traversal Order: [0, 1, 2, 3, 4, 5]
}
