// measure2d.rs
pub mod measure2d {
    pub trait Area {
        fn calculate_area(&self) -> f64;
    }

    pub trait Perimeter {
        fn calculate_perimeter(&self) -> f64;
    }

    pub struct Square {
        side_length: f64,
    }

    impl Area for Square {
        fn calculate_area(&self) -> f64 {
            self.side_length * self.side_length
        }
    }

    impl Perimeter for Square {
        fn calculate_perimeter(&self) -> f64 {
            4.0 * self.side_length
        }
    }

    pub struct Circle {
        radius: f64,
    }

    impl Area for Circle {
        fn calculate_area(&self) -> f64 {
            std::f64::consts::PI * self.radius * self.radius
        }
    }
}

// measure3d.rs
pub mod measure3d {
    pub trait Volume {
        fn calculate_volume(&self) -> f64;
    }

    pub trait SurfaceArea {
        fn calculate_surface_area(&self) -> f64;
    }

    pub struct Cube {
        side_length: f64,
    }

    impl Volume for Cube {
        fn calculate_volume(&self) -> f64 {
            self.side_length * self.side_length * self.side_length
        }
    }

    impl SurfaceArea for Cube {
        fn calculate_surface_area(&self) -> f64 {
            6.0 * self.side_length * self.side_length
        }
    }

    pub struct Sphere {
        radius: f64,
    }

    impl Volume for Sphere {
        fn calculate_volume(&self) -> f64 {
            (4.0 / 3.0) * std::f64::consts::PI * self.radius * self.radius * self.radius
        }
    }

    impl SurfaceArea for Sphere {
        fn calculate_surface_area(&self) -> f64 {
            4.0 * std::f64::consts::PI * self.radius * self.radius
        }
    }
}

