}

#[derive(Debug)]
struct NvmfAttach {
    uuid: String,
    port: u16,
}

impl NvmfAttach {
    fn new(uuid: String, port: u16) -> Self {
        NvmfAttach { uuid, port }
    }
}

fn extract_uuid(uuid_str: &str) -> Result<String, ParseIntError> {
    uuid_str.parse::<uuid::Uuid>().map(|uuid| uuid.to_string()).map_err(|_| ParseIntError)
}

fn parse_nqn(url: &str) -> Result<NvmfAttach, DeviceError> {
    let components: Vec<&str> = url.split(':').collect();

    if components.len() != 2 {
        return Err(DeviceError::new("invalid NQN"));
    }

    let uuid = extract_uuid(components[1]).map_err(|error| {
        DeviceError::from(format!("invalid UUID: {}", error))
    })?;

    let port = url.port().unwrap_or(4420);

    Ok(NvmfAttach::new(uuid, port))
}

fn main() {
    let nqn_url = "subsystem1:123e4567-e89b-12d3-a456-426614174000";
    match parse_nqn(nqn_url) {
        Ok(nvmf_attach) => println!("Parsed NVMf Attach: {:?}", nvmf_attach),
        Err(err) => println!("Error parsing NVMf Attach: {:?}", err),
    }
}
