mod library {
    pub struct Book {
        title: String,
        author: String,
        available: bool,
    }

    impl Book {
        pub fn new(title: &str, author: &str) -> Book {
            Book {
                title: title.to_string(),
                author: author.to_string(),
                available: true,
            }
        }
    }

    pub struct Library {
        books: Vec<Book>,
    }

    impl Library {
        pub fn new() -> Library {
            Library { books: Vec::new() }
        }

        pub fn add_book(&mut self, title: &str, author: &str) {
            let new_book = Book::new(title, author);
            self.books.push(new_book);
        }

        pub fn remove_book(&mut self, title: &str) {
            self.books.retain(|book| book.title != title);
        }

        pub fn search_book(&self, title: &str) -> Option<&Book> {
            self.books.iter().find(|&book| book.title == title)
        }

        pub fn checkout_book(&mut self, title: &str) -> Result<(), &str> {
            if let Some(book) = self.books.iter_mut().find(|book| book.title == title && book.available) {
                book.available = false;
                Ok(())
            } else {
                Err("Book not found or already checked out")
            }
        }

        pub fn return_book(&mut self, title: &str) -> Result<(), &str> {
            if let Some(book) = self.books.iter_mut().find(|book| book.title == title && !book.available) {
                book.available = true;
                Ok(())
            } else {
                Err("Book not found or already available")
            }
        }
    }
}

fn main() {
    let mut library = library::Library::new();
    library.add_book("The Catcher in the Rye", "J.D. Salinger");
    library.add_book("To Kill a Mockingbird", "Harper Lee");

    println!("Library books:");
    for book in &library.books {
        println!("{} by {} - Available: {}", book.title, book.author, book.available);
    }

    if let Some(book) = library.search_book("To Kill a Mockingbird") {
        println!("Found book: {} by {} - Available: {}", book.title, book.author, book.available);
    }

    library.checkout_book("The Catcher in the Rye").unwrap();
    println!("After checking out 'The Catcher in the Rye':");
    for book in &library.books {
        println!("{} by {} - Available: {}", book.title, book.author, book.available);
    }

    library.return_book("The Catcher in the Rye").unwrap();
    println!("After returning 'The Catcher in the Rye':");
    for book in &library.books {
        println!("{} by {} - Available: {}", book.title, book.author, book.available);
    }
}
