    pub fn new(data: &'a mut T) -> SafeRef<'a, T> {
        SafeRef { data }
    }
}

impl<'a, T> Deref for SafeRef<'a, T> {
    type Target = T;

    fn deref(&self) -> &T {
        &*self.data
    }
}

impl<'a, T> DerefMut for SafeRef<'a, T> {
    fn deref_mut(&mut self) -> &mut T {
        &mut *self.data
    }
}

