```rust
use std::collections::HashMap;

struct Query {
    data: HashMap<String, Vec<String>>,
    query_string: Option<String>,
}

impl Query {
    fn new(query_string: Option<String>) -> Query {
        let data = HashMap::new();
        Query {
            data,
            query_string,
        }
    }
}

fn decode_query_string(query_string: &str) -> Query {
    let mut data = HashMap::new();

    for pair in query_string.split('&') {
        let mut iter = pair.split('=');
        if let (Some(key), Some(value)) = (iter.next(), iter.next()) {
            let key = url_decode(key);
            let value = url_decode(value);
            let mut query_vec = data.entry(key.to_owned()).or_insert(Vec::new());
            query_vec.push(value.to_owned());
        }
    }

    Query {
        data,
        query_string: Some(query_string.to_owned()),
    }
}

fn url_decode(s: &str) -> String {
    let s = s.replace("+", " ");
    percent_encoding::percent_decode_str(&s)
        .decode_utf8()
        .map(|s| s.to_string())
        .unwrap_or_else(|_| s.to_string())
}
```

