#[derive(Debug, PartialEq, Eq, Hash)]
enum ResourceType {
    Feathers,
    Sticks,
    Logs,
}

fn calculate_total_price(resources: Vec<(ResourceType, u32)>) -> u32 {
    let mut resource_prices: HashMap<ResourceType, u32> = HashMap::new();
    resource_prices.insert(ResourceType::Feathers, 500);
    resource_prices.insert(ResourceType::Sticks, 350);
    resource_prices.insert(ResourceType::Logs, 150);

    let mut total_price = 0;
    for (resource, factor) in resources {
        if let Some(&base_price) = resource_prices.get(&resource) {
            total_price += base_price * factor;
        }
    }
    total_price
}
