    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AppError::Git(err) => write!(f, "Git error: {}", err),
            AppError::Editor => write!(f, "Editor error"),
            AppError::Build(msg) => write!(f, "Fail to build plugin: {}", msg),
            AppError::PluginNotInstalled => write!(f, "Plugin is not installed"),
        }
    }
}

// Create a function to handle errors and convert git2::Error into AppError::Git
fn handle_error<T, E>(result: Result<T, E>) -> Result<T, AppError>
