struct Agent {
    // Define the fields of the Agent struct
}

#[derive(Debug)]
enum Command {
    Create(Agent),
    Update(Agent),
    Delete(String),
}

#[derive(Debug)]
struct ProcessedCommands {
    created_agents: Vec<Agent>,
    updated_agents: Vec<Agent>,
    deleted_agent_ids: Vec<String>,
}

struct CommandProcessor {
    create: Vec<Command>,
    update: Vec<Command>,
    delete: Vec<Command>,
}

impl CommandProcessor {
    fn new() -> Self {
        CommandProcessor {
            create: Vec::new(),
            update: Vec::new(),
            delete: Vec::new(),
        }
    }

    fn process_commands(&mut self, commands: Vec<Command>) -> Result<ProcessedCommands, String> {
        let mut created_agents = Vec::new();
        let mut updated_agents = Vec::new();
        let mut deleted_agent_ids = Vec::new();

        for command in commands {
            match command {
                Command::Create(agent) => {
                    created_agents.push(agent);
                }
                Command::Update(agent) => {
                    updated_agents.push(agent);
                }
                Command::Delete(agent_id) => {
                    deleted_agent_ids.push(agent_id);
                }
            }
        }

        self.create.clear();
        self.update.clear();
        self.delete.clear();

        Ok(ProcessedCommands {
            created_agents,
            updated_agents,
            deleted_agent_ids,
        })
    }
}

