// serializer.rs
use crate::util;

#[derive(Debug, PartialEq)]
pub struct Person {
    name: String,
    age: u32,
    is_student: bool,
}

impl Person {
    pub fn new(name: String, age: u32, is_student: bool) -> Person {
        Person { name, age, is_student }
    }
}

pub fn serialize_person(person: &Person) -> Vec<u8> {
    let mut serialized_data = Vec::new();
    serialized_data.extend_from_slice(&util::string_to_bytes(&person.name));
    serialized_data.extend_from_slice(&person.age.to_le_bytes());
    serialized_data.push(if person.is_student { 1 } else { 0 });
    serialized_data
}

pub fn deserialize_person(data: &[u8]) -> Option<Person> {
    if data.len() < 5 {
        return None; // Insufficient data for deserialization
    }

    let name_length = u32::from_le_bytes([data[0], data[1], data[2], data[3]]) as usize;
    if data.len() < name_length + 5 {
        return None; // Invalid data length
    }

    let name = util::bytes_to_string(&data[4..4 + name_length]);
    let age = u32::from_le_bytes([data[name_length + 4], data[name_length + 5], data[name_length + 6], data[name_length + 7]]);
    let is_student = data[name_length + 8] != 0;

    Some(Person { name, age, is_student })
}

// util.rs
pub fn string_to_bytes(s: &str) -> Vec<u8> {
    s.as_bytes().len() as u32
        .to_le_bytes()
        .iter()
        .cloned()
        .chain(s.as_bytes().iter().cloned())
        .collect()
}

pub fn bytes_to_string(data: &[u8]) -> String {
    let length = u32::from_le_bytes([data[0], data[1], data[2], data[3]]) as usize;
    String::from_utf8_lossy(&data[4..4 + length]).into_owned()
}
```

In the solution, the `serialize_person` function serializes the `Person` object into a custom binary format, and the `deserialize_person` function deserializes the binary data back into a `Person` object. The `util` module provides utility functions for converting strings to bytes and vice versa. The serialization format includes the length of the name as a 4-byte integer in little-endian format, followed by the name as bytes, the age as a 4-byte integer in little-endian format, and a single byte representing the boolean `is_student` field. The deserialization function checks for data integrity and length to ensure a valid deserialization process.

