struct ResourceManager {
    acquired_resources: std::collections::HashSet<u32>,
}

impl ResourceManager {
    fn new() -> Self {
        ResourceManager {
            acquired_resources: std::collections::HashSet::new(),
        }
    }

    fn acquire(&mut self, resource_id: u32) -> Result<(), String> {
        if self.acquired_resources.contains(&resource_id) {
            Err(format!("Resource {} is already acquired", resource_id))
        } else {
            self.acquired_resources.insert(resource_id);
            Ok(())
        }
    }

    fn release(&mut self, resource_id: u32) -> Result<(), String> {
        if self.acquired_resources.contains(&resource_id) {
            self.acquired_resources.remove(&resource_id);
            Ok(())
        } else {
            Err(format!("Resource {} is not acquired", resource_id))
        }
    }

    fn finalize(&mut self) {
        self.acquired_resources.clear();
    }
}

fn main() {
    let mut manager = ResourceManager::new();
    manager.acquire(1).unwrap();
    manager.acquire(2).unwrap();
    manager.release(1).unwrap();
    manager.finalize();
}
```

