use super::Expression;
use crate::{DeclId, Span, Spanned};

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Argument {
    Positional(Expression),
    Named((Spanned<String>, Option<Spanned<String>>, Option<Expression>)),
}

fn parse_arguments(tokens: Vec<Token>) -> Result<Vec<Argument>, String> {
    let mut parsed_arguments = Vec::new();

    for token in tokens {
        match token {
            Token::ExprToken(expr) => {
                let expression = Expression::new(expr);
                parsed_arguments.push(Argument::Positional(expression));
            }
            Token::NamedToken(name, type_opt, expr) => {
                let name_spanned = Spanned::new(name);
                let type_spanned = type_opt.map(|t| Spanned::new(t));
                let expr_opt = expr.map(|e| Expression::new(e));
                parsed_arguments.push(Argument::Named((name_spanned, type_spanned, expr_opt)));
            }
        }
    }

    Ok(parsed_arguments)
}
```

In the solution, we iterate through the input tokens and match each token to its corresponding variant. For `ExprToken`, we create a new `Expression` and push it as a `Positional` argument. For `NamedToken`, we create `Spanned` instances for the name and type, and an `Expression` if present, and push them as a `Named` argument. Finally, we return the parsed list of `Argument` instances.

