fn roll_dice(rolls_count: &mut i32, outcome_frequency: &mut HashMap<i32, i32>) -> i32 {
    // Simulate the rolling of two dice
    let dice1 = rand::random::<i32>() % 6 + 1;
    let dice2 = rand::random::<i32>() % 6 + 1;
    let sum = dice1 + dice2;

    // Update the frequency of the outcome
    let count = outcome_frequency.entry(sum).or_insert(0);
    *count += 1;

    // Update the total number of rolls
    *rolls_count += 1;

    sum
}

fn main() {
    let mut rolls_count: i32 = 0;
    let mut outcome_frequency: HashMap<i32, i32> = HashMap::new();

    for _ in 0..1000 {
        let result = roll_dice(&mut rolls_count, &mut outcome_frequency);
        // Display the result of each roll
        println!("Result of the roll: {}", result);
    }

    // Display the total number of rolls and the frequency of each outcome
    println!("Total number of rolls: {}", rolls_count);
    for (outcome, frequency) in &outcome_frequency {
        println!("Outcome {} occurred {} times", outcome, frequency);
    }
}
```

