fn task1(lines: &Vec<usize>, bitcount: usize) -> usize {
    let half_length = ((lines.len() as f32) / 2.0 + 0.5) as usize;
    let frequency = calculate_frequency(lines, bitcount);

    let gamma_rate = calculate_gamma_rate(&frequency, half_length, bitcount);
    let epsilon_rate = calculate_epsilon_rate(gamma_rate, bitcount);

    gamma_rate * epsilon_rate
}

fn calculate_frequency(lines: &Vec<usize>, bitcount: usize) -> Vec<usize> {
    let mut frequency: Vec<usize> = vec![0; bitcount];
    for line in lines {
        for i in 0..bitcount {
            if (line >> i) & 1 == 1 {
                frequency[i] += 1;
            }
        }
    }
    frequency
}

fn calculate_gamma_rate(frequency: &Vec<usize>, half_length: usize, bitcount: usize) -> usize {
    let mut gamma_rate = 0;
    for i in 0..bitcount {
        gamma_rate += (frequency[i] as f32 / half_length as f32).powi(2);
    }
    (gamma_rate * 1000.0) as usize
}

fn calculate_epsilon_rate(gamma_rate: usize, bitcount: usize) -> usize {
    let epsilon_rate = (gamma_rate as f32 / bitcount as f32).sqrt();
    epsilon_rate as usize
}
```
In the solution, the `task1` function calculates the `half_length`, frequency, gamma rate, and epsilon rate based on the given requirements. The `calculate_frequency` function computes the frequency of each bit position across all lines. The `calculate_gamma_rate` function computes the gamma rate based on the frequency and half length. The `calculate_epsilon_rate` function computes the epsilon rate based on the gamma rate and bit count. Finally, the `task1` function returns the product of the gamma rate and epsilon rate as the calculated metric.

