pub fn karatsuba_mul(v1: &[u8], v2: &[u8]) -> Vec<u8> {
    if v1.len() == 1 || v2.len() == 1 {
        // Base case: Perform simple multiplication for single-digit numbers
        let mut result = vec![0; v1.len() + v2.len() - 1];
        for (i, &digit1) in v1.iter().enumerate() {
            for (j, &digit2) in v2.iter().enumerate() {
                result[i + j] += digit1 * digit2;
            }
        }
        return result;
    }

    let n = v1.len().max(v2.len());
    let m = (n + 1) / 2;

    let (a0, a1) = v1.split_at(v1.len().saturating_sub(m));
    let (b0, b1) = v2.split_at(v2.len().saturating_sub(m));

    let z0 = karatsuba_mul(a0, b0);
    let z2 = karatsuba_mul(a1, b1);

    let mut a0_a1 = a0.to_vec();
    a0_a1.extend_from_slice(a1);
    let mut b0_b1 = b0.to_vec();
    b0_b1.extend_from_slice(b1);
    let z1 = karatsuba_mul(&a0_a1, &b0_b1);
    let z1 = z1.iter().zip(z0.iter().chain(std::iter::repeat(&0))).zip(z2.iter().chain(std::iter::repeat(&0)))
        .map(|((&z1, &z0), &z2)| z1 - z0 - z2)
        .collect();

    let mut result = vec![0; 2 * m];
    for (i, &z) in z0.iter().enumerate() {
        result[i] += z;
    }
    for (i, &z) in z1.iter().enumerate() {
        result[i + m] += z;
    }
    for (i, &z) in z2.iter().enumerate() {
        result[i + 2 * m] += z;
    }
    result
}
```

This solution implements the `karatsuba_mul` function using the Karatsuba algorithm. It handles the base case for single-digit numbers and recursively applies the algorithm to perform efficient multiplication of large numbers. The algorithm reduces the number of multiplications required for large numbers, improving the overall efficiency of the multiplication operation.

