pub fn impl_macro(ast: &syn::DeriveInput) -> TokenStream {
    let name = &ast.ident;

    let gen = quote! {
        impl CacheableResponse for #name {
            fn is_cacheable(&self) -> bool {
                if let syn::Data::Struct(data) = &ast.data {
                    for field in &data.fields {
                        if let Some(ident) = &field.ident {
                            if ident == "cacheable" {
                                if let syn::Type::Path(path) = &field.ty {
                                    if path.path.is_ident("bool") {
                                        return true; // Use the cacheable field to determine cacheability
                                    }
                                }
                            }
                        }
                    }
                }
                true // Default to true if no cacheable field is found
            }

            fn cache_key(&self) -> String {
                stringify!(#name).to_string() // Use the struct's name as the cache key
            }
        }
    };

    gen.into()
}
