fn calculate_total_gravitational_force(
    entity_position: (f32, f32),
    entity_gravity: &Gravity,
    other_entities: &[(&Gravity, (f32, f32))]
) -> (f32, f32) {
    const G: f32 = 6.67430e-11; // Gravitational constant
    const entity_mass: f32 = 1.0; // Mass of the entity

    let mut total_force_x = 0.0;
    let mut total_force_y = 0.0;

    for (other_gravity, other_position) in other_entities {
        if let (Some(other_x), Some(other_y)) = (other_gravity.x, other_gravity.y) {
            let dx = other_position.0 - entity_position.0;
            let dy = other_position.1 - entity_position.1;
            let distance_squared = dx * dx + dy * dy;
            let force_magnitude = G * entity_mass * 1.0 / distance_squared; // Assuming mass of each entity is 1.0

            total_force_x += force_magnitude * dx / distance_squared;
            total_force_y += force_magnitude * dy / distance_squared;
        }
    }

    (total_force_x, total_force_y)
}
```

This solution calculates the total gravitational force acting on the entity due to the gravitational pull of other entities in the system. It iterates through each other entity, calculates the force components in the x and y directions, and accumulates the total force. The gravitational constant and mass of the entity are used to calculate the force magnitude based on Newton's law of universal gravitation.

