impl Register {
    // Set the CRC operation type in the register
    pub fn set_crc_ctrl_type(&mut self, value: CRC_CTRL_TYPER) -> &mut Self {
        // Clear the bits representing the CRC operation type
        self.w.bits &= !(3 << 13);
        // Set the bits with the new CRC operation type value
        self.w.bits |= match value {
            CRC_CTRL_TYPER::Type1 => 0 << 13,
            CRC_CTRL_TYPER::Type2 => 1 << 13,
            CRC_CTRL_TYPER::Type3 => 2 << 13,
            // Handle additional CRC operation types if needed
        };
        self
    }

    // Get the CRC operation type from the register
    pub fn get_crc_ctrl_type(&self) -> CRC_CTRL_TYPER {
