use image::{ImageBuffer, Rgb};

fn calculate_centroid(image: &ImageBuffer<Rgb<u8>, Vec<u8>>) -> (f64, f64) {
    let mut total_x = 0;
    let mut total_y = 0;
    let mut count = 0;

    for (x, y, pixel) in image.enumerate_pixels() {
        if pixel.0 != [0, 0, 0] {
            total_x += x as i32;
            total_y += y as i32;
            count += 1;
        }
    }

    if count == 0 {
        return (0.0, 0.0); // No non-black pixels, centroid at origin
    }

    (total_x as f64 / count as f64, total_y as f64 / count as f64)
}
```

This solution iterates through all the pixels in the image, accumulating the x and y coordinates of non-black pixels and counting them. Then, it calculates the average position of these non-black pixels to determine the centroid of the image. If there are no non-black pixels, the centroid is considered to be at the origin (0, 0).

