    let matches = App::new("my_program")
        .subcommand(
            App::new("open")
                .about("Open a path/URL with its default handler")
                .arg(
                    Arg::new("paths")
                        .about("Paths or URLs to open")
                        .multiple_values(true)
                        .required(true),
                ),
        )
        .get_matches();

