pub(crate) type HostString = CString;

/// Convert an `OsString` to a `HostString`.
pub(crate) fn hoststring_from_osstring(os: OsString) -> HostString {
    let vec = os.into_vec();
    assert!(!vec.contains(&b'\0')); // Ensure the input does not contain NUL bytes

