use rand::prelude::*;

#[allow(missing_copy_implementations)]
#[derive(Clone, Debug, PartialEq)]
pub struct SwapOrderMutator {
    mutation_rate: f64,
}

impl SwapOrderMutator {
    pub fn new(mutation_rate: f64) -> Self {
        Self { mutation_rate }
    }

    pub fn mutate<T>(&self, genome: &mut Vec<T>, rng: &mut ThreadRng) -> &Vec<T> {
        if rng.gen::<f64>() < self.mutation_rate {
            let genome_length = genome.len();
            let (locus1, locus2) = random_cut_points(rng, genome_length);
            let value2 = genome.remove(locus2);
            genome.insert(locus1 + 1, value2);
        }
        genome
    }
}

fn random_cut_points(rng: &mut ThreadRng, genome_length: usize) -> (usize, usize) {
    let locus1 = rng.gen_range(0, genome_length);
    let locus2 = rng.gen_range(0, genome_length);
    (locus1, locus2)
}
```

