fn send_stun_binding_request(
    turn_client: UdpOverTurnTransporter,
    stun_server_addr: SocketAddr,
) -> Result<Response<rfc5389::Attribute>, Error> {
    // Create a STUN channel using the TURN client
    let stun_channel = Channel::new(StunUdpTransporter::new(turn_client));

    // Create a STUN client using the STUN channel
    let stun_client = Client::new(&Handle::current(), stun_channel);

