use std::fmt;

enum SubsortOrder {
    QueryName(Vec<String>),
    Coordinate(Vec<String>),
}

impl fmt::Display for SubsortOrder {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SubsortOrder::QueryName(names) => {
                let mut sorted_names = names.clone();
                sorted_names.sort();
                write!(f, "Sorted QueryName: {:?}", sorted_names)
            }
            SubsortOrder::Coordinate(coords) => {
                let mut sorted_coords = coords.clone();
                sorted_coords.sort_by(|a, b| {
                    let a_parts: Vec<&str> = a.split(':').collect();
                    let b_parts: Vec<&str> = b.split(':').collect();
                    let a_ref_seq = a_parts[0];
                    let b_ref_seq = b_parts[0];
                    let a_pos: i32 = a_parts[1].parse().unwrap();
                    let b_pos: i32 = b_parts[1].parse().unwrap();
                    if a_ref_seq != b_ref_seq {
                        a_ref_seq.cmp(&b_ref_seq)
                    } else {
                        a_pos.cmp(&b_pos)
                    }
                });
                write!(f, "Sorted Coordinate: {:?}", sorted_coords)
            }
        }
    }
}

fn main() {
    let query_names = SubsortOrder::QueryName(vec![
        "John".to_string(),
        "Alice".to_string(),
        "Bob".to_string(),
    ]);
    println!("{}", query_names);

    let coordinates = SubsortOrder::Coordinate(vec![
        "chr1:100".to_string(),
        "chr2:50".to_string(),
        "chr1:200".to_string(),
    ]);
    println!("{}", coordinates);
}
```

In this solution, the `fmt::Display` trait is implemented for the `SubsortOrder` enum. The `fmt::Display` implementation sorts the strings based on the variant and formats the sorted order accordingly. For the `QueryName` variant, the strings are sorted lexicographically, and for the `Coordinate` variant, the strings are sorted first by reference sequence and then by position. The `main` function demonstrates the usage of the `fmt::Display` implementation for both variants.

