use diesel::prelude::*;
use diesel::dsl::insert_into;
use diesel::pg::upsert::excluded;

fn process_user_records(records: Vec<User>, conn: &PgConnection) {
    for record in records {
        let existing_user = users::table.filter(users::id.eq(record.id)).first::<User>(conn).optional();

        match existing_user {
            Ok(Some(user)) => {
                if user.name != record.name {
                    diesel::update(users::table.filter(users::id.eq(record.id)))
                        .set(users::name.eq(record.name))
                        .execute(conn)
                        .unwrap();
                }
            }
            Ok(None) => {
                let _ = insert_into(users::table)
                    .values(&record)
                    .on_conflict(users::name)
                    .do_nothing()
                    .execute(conn);
            }
            Err(err) => {
                eprintln!("Error processing user record: {}", err);
            }
        }
    }
}
```

