fn marble_mania(players: u32, last_marble: u32) -> u32 {
    let mut circle = vec![0];
    let mut scores = vec![0; players as usize];
    let mut current_player = 0;
    let mut current_marble = 0;

    for marble in 1..=last_marble {
        if marble % 23 == 0 {
            let remove_index = (current_marble + circle.len() - 7) % circle.len();
            scores[current_player as usize] += marble + circle.remove(remove_index);
            current_marble = remove_index as u32;
        } else {
            let insert_index = (current_marble + 2) % circle.len();
            circle.insert(insert_index as usize, marble);
            current_marble = insert_index as u32;
        }
        current_player = (current_player + 1) % players;
    }

    *scores.iter().max().unwrap()
}

fn main() {
    let players = 30;
    let last_marble = 5807;
    println!("{}", marble_mania(players, last_marble)); // Output: 37305
