The function `fold_paper(&origami)` should return the folded shape after applying the folding instructions.

```rust
fn fold_paper(origami: &Origami) -> Vec<Point> {
    let mut folded_points = origami.points.clone();

    for fold in &origami.folds {
        match fold {
            Fold::Vertical { x } => {
                for point in &mut folded_points {
                    if point.x > *x {
                        point.x = 2 * x - point.x;
                    }
                }
            }
            Fold::Horizontal { y } => {
                for point in &mut folded_points {
                    if point.y > *y {
                        point.y = 2 * y - point.y;
                    }
                }
            }
        }
    }

    folded_points
