}

impl IntCollection {
    fn new() -> Self {
        IntCollection {
            counts: HashMap::new(),
            values: Vec::new(),
        }
    }

    fn add(&mut self, value: i32) {
        if let Some(count) = self.counts.get_mut(&value) {
            *count += 1;
        } else {
            self.counts.insert(value, 1);
            self.values.push(value);
        }
