    let pattern = "abr";
    let matches = find_pattern_matches(text, pattern);
    println!("Pattern matches found at indices: {:?}", matches);
}

fn find_pattern_matches(text: &str, pattern: &str) -> Vec<usize> {
    let mut matches = Vec::new();
    let text_bytes = text.as_bytes();
    let pattern_bytes = pattern.as_bytes();
    let text_len = text_bytes.len();
    let pattern_len = pattern_bytes.len();

    if pattern_len > text_len {
        return matches;
    }

    let mut i = 0;
    while i <= text_len - pattern_len {
        let mut j = 0;
        while j < pattern_len && pattern_bytes[j] == text_bytes[i + j] {
            j += 1;
        }
        if j == pattern_len {
            matches.push(i);
        }
        i += 1;
    }

    matches
}
```

