use std::collections::HashSet;

pub struct VectorEntry {
    next_version: LogTime,
    // other fields and methods are omitted for brevity
}

impl VectorEntry {
    pub fn is_ready(&self, clk: LogTime) -> bool {
        clk < self.next_version && self.no_exceptions(clk)
    }

    pub fn diff_from(&self, other: &Self) -> HashSet<LogTime> {
        let local_ops = (other.next_version..self.next_version).filter(|ix: &LogTime| self.no_exceptions(*ix));
        let remote_ops = (self.next_version..other.next_version).filter(|ix: &LogTime| other.no_exceptions(*ix));

        let local_ops_set: HashSet<LogTime> = local_ops.collect();
        let remote_ops_set: HashSet<LogTime> = remote_ops.collect();

        local_ops_set.difference(&remote_ops_set).cloned().collect()
    }
}
```

