impl Cpu {
    fn schedule_processes(&self) -> Vec<u32> {
        let mut waiting_time = 0;
        let mut scheduled_processes: Vec<u32> = Vec::new();

        // Sort processes by burst time
        let mut sorted_processes = self.processes.clone();
        sorted_processes.sort_by(|a, b| a.burst_time.cmp(&b.burst_time));

        for process in &sorted_processes {
            scheduled_processes.push(process.id);
            waiting_time += process.burst_time;
        }

        scheduled_processes
    }
}

