struct NotificationLibrary {
    subscriptions: std::collections::HashMap<String, Vec<Box<dyn Fn() + Send>>>,
}

impl NotificationLibrary {
    fn new() -> Self {
        NotificationLibrary {
            subscriptions: std::collections::HashMap::new(),
        }
    }

    fn subscribe(&mut self, event: String, callback: Box<dyn Fn() + Send>) {
        self.subscriptions
            .entry(event)
            .or_insert_with(Vec::new)
            .push(callback);
    }

    fn notify(&self, event: &str) {
        if let Some(callbacks) = self.subscriptions.get(event) {
            for callback in callbacks {
                callback();
            }
        }
    }
}

impl Drop for NotificationLibrary {
    fn drop(&mut self) {
        // Perform any necessary cleanup or resource release here
        println!("NotificationLibrary is being dropped");
    }
}

fn main() {
    let mut notification_library = NotificationLibrary::new();

    let callback1 = Box::new(|| println!("Callback 1 executed"));
    let callback2 = Box::new(|| println!("Callback 2 executed"));

    notification_library.subscribe("event1".to_string(), callback1);
    notification_library.subscribe("event2".to_string(), callback2);

    notification_library.notify("event1");
    notification_library.notify("event2");
}
```

