fn smallest_window(char_sequence: &[(char, usize)], target_chars: &str) -> Option<(usize, usize)> {
    use std::collections::HashMap;

    let mut char_size: HashMap<char, i32> = HashMap::new();
    for c in target_chars.chars() {
        *char_size.entry(c).or_insert(0) += 1;
    }

    let mut range: Option<(usize, usize)> = None;
    let mut count = 0;
    let mut left = 0;

    for (right, (ch, _)) in char_sequence.iter().enumerate() {
        if let Some(&size) = char_size.get(ch) {
            if size > 0 {
                count += 1;
            }
            char_size.insert(*ch, size - 1);
        }

        while count == target_chars.len() {
            if let Some((start, end)) = range {
                if range.map_or(true, |(s, e)| e - s > right - left) {
                    range = Some((left, right));
                }
            }
            if let Some(&size) = char_size.get_mut(&char_sequence[left].0) {
                if size >= 0 {
                    count -= 1;
                }
                char_size.insert(char_sequence[left].0, size + 1);
            }
            left += 1;
        }
    }

    range
}
