use serde_json::Value;

struct GroqQuery {
    field: String,
    condition: String,
    value: String,
}

fn evaluate_query(queries: &Vec<GroqQuery>, json: &Value) -> Vec<bool> {
    queries
        .iter()
        .map(|query| {
            if let Some(field_value) = json.get(&query.field) {
                match &query.condition[..] {
                    "eq" => field_value == &json[&query.value],
                    "gt" => field_value.as_i64().unwrap_or(0) > query.value.parse().unwrap_or(0),
                    "lt" => field_value.as_i64().unwrap_or(0) < query.value.parse().unwrap_or(0),
                    _ => false,
                }
            } else {
                false
            }
        })
        .collect()
}

fn main() {
    let queries = vec![
        GroqQuery {
            field: "age".to_string(),
            condition: "gt".to_string(),
            value: "25".to_string(),
        },
        GroqQuery {
            field: "name".to_string(),
            condition: "eq".to_string(),
            value: "John".to_string(),
        },
    ];

    let json = json!({
        "name": "John",
        "age": 30,
        "city": "New York"
    });

    let result = evaluate_query(&queries, &json);
    println!("{:?}", result); // Output: [true, true]
}
