// Definition of the OrderedMap data structure
struct OrderedMap<K, V> {
    map: HashMap<K, V>,
    keys: Vec<K>,
}

impl<K, V> OrderedMap<K, V> {
    // Implementation of the new function to create a new empty OrderedMap
    fn new() -> Self {
        OrderedMap {
            map: HashMap::new(),
            keys: Vec::new(),
        }
    }

    // Implementation of the insert function to insert key-value pairs into the map
    fn insert(&mut self, key: K, value: V) {
        if !self.map.contains_key(&key) {
            self.keys.push(key.clone());
        }
        self.map.insert(key, value);
    }
}

fn main() {
    // Example usage
    let mut map = OrderedMap::new();
    map.insert("a", 1);
    map.insert("b", 2);
    map.insert("c", 3);

    for key in map.keys {
        println!("Key: {}, Value: {}", key, map.map[&key]);
    }
}
