use std::sync::{Arc, Mutex};
use std::thread;

pub struct Scheduler {
    tasks: Arc<Mutex<Vec<Box<dyn Fn() + Send>>>>,
}

impl Scheduler {
    pub fn new() -> Self {
        Scheduler {
            tasks: Arc::new(Mutex::new(Vec::new())),
        }
    }

    pub fn schedule_task(&self, task: Box<dyn Fn() + Send>) {
        self.tasks.lock().unwrap().push(task);
    }

    pub fn run(&self) {
        let tasks = Arc::clone(&self.tasks);
        let handles: Vec<_> = self.tasks.lock().unwrap().iter().map(|task| {
            let tasks = Arc::clone(&tasks);
            thread::spawn(move || {
                task();
                let mut locked_tasks = tasks.lock().unwrap();
                locked_tasks.retain(|t| !Arc::ptr_eq(&task, t));
            })
        }).collect();

        for handle in handles {
            handle.join().unwrap();
        }
    }
}
```

In this solution, we define a `Scheduler` struct with the specified methods. The `schedule_task` method adds the provided task to the list of scheduled tasks, and the `run` method executes all the scheduled tasks concurrently using threads. The tasks are stored in a shared `Arc<Mutex<Vec<Box<dyn Fn() + Send>>>>` to ensure thread safety and allow concurrent access to the task list. Each task is executed in a separate thread, and upon completion, it is removed from the task list to prevent duplicate execution.

