fn convert_to_rgba(rgb_data: Vec<u8>) -> Vec<u8> {
    let mut rgba_data = Vec::with_capacity(rgb_data.len() / 3 * 4);

    for rgb in rgb_data.chunks(3) {
        rgba_data.push(rgb[0]); // Red component
        rgba_data.push(rgb[1]); // Green component
        rgba_data.push(rgb[2]); // Blue component
        rgba_data.push(255);    // Alpha component (fully opaque)
    }

    rgba_data
}
