```rust
fn num_range_filter(nums: &[i32]) -> Option<Vec<i32>> {
    if nums.is_empty() {
        return None;
    }

    let min = *nums.iter().min().unwrap();
    let max = *nums.iter().max().unwrap();

    let filtered_nums: Vec<i32> = nums.iter()
        .filter(|&num| *num >= min && *num <= max)
        .cloned()
        .collect();

    Some(filtered_nums)
}
```

