fn erf_inv(x: f64) -> f64 {
    if x < -1.0 || x > 1.0 {
        panic!("Input value must be in the range [-1, 1]");
    }

    if x == 0.0 {
        return 0.0;
    }

    let mut result = 0.0;
    let abs_x = x.abs();

    if abs_x < 0.75 {
        // Polynomial coefficients for the interval [0, 0.75]
        let coefficients: &[f64] = &[
            0.0,
            0.15504700031159,
            0.756591622661243,
            1.123148979543285,
            0.295273603878299,
            0.056393987933128,
            0.000045138265701,
        ];

        for (i, &coef) in coefficients.iter().enumerate() {
            result += coef * abs_x.powf(i as f64);
        }
        result *= abs_x;
    } else if abs_x < 1.0 {
        // Polynomial coefficients for the interval [0.75, 1] with x greater than 44
        let coefficients: &[f64] = &[
            1.0,
            0.0845746234001899436914,
            // more coefficients...
        ];

        for (i, &coef) in coefficients.iter().enumerate() {
            result += coef * abs_x.powf(i as f64);
        }
    }

    if x < 0.0 {
        -result
    } else {
        result
    }
}
```

