use std::collections::HashMap;

// Structure to store response times for each application layer
struct ResponseTimes {
    times: Vec<f64>,
}

impl ResponseTimes {
    fn new() -> ResponseTimes {
        ResponseTimes { times: Vec::new() }
    }

    fn record_response_time(&mut self, time: f64) {
        self.times.push(time);
    }

    fn calculate_average_response_time(&self) -> Option<f64> {
        let sum: f64 = self.times.iter().sum();
        let count = self.times.len() as f64;
        if count > 0 {
            Some(sum / count)
        } else {
            None
        }
    }
}

// HashMap to store response times for each application layer
static mut RESPONSE_TIMES: Option<HashMap<String, ResponseTimes>> = None;

fn get_response_times_map() -> &'static mut HashMap<String, ResponseTimes> {
    unsafe {
        if RESPONSE_TIMES.is_none() {
            RESPONSE_TIMES = Some(HashMap::new());
        }
        RESPONSE_TIMES.as_mut().unwrap()
    }
}

fn record_response_time(app_layer: &str, time: f64) {
    let response_times_map = get_response_times_map();
    let response_times = response_times_map.entry(app_layer.to_string()).or_insert(ResponseTimes::new());
    response_times.record_response_time(time);
}

fn calculate_average_response_time(app_layer: &str) -> Option<f64> {
    let response_times_map = get_response_times_map();
    if let Some(times) = response_times_map.get(app_layer) {
        times.calculate_average_response_time()
    } else {
        None
    }
}
