use std::collections::HashMap;

fn parse_configuration(config_module: &str) -> HashMap<String, String> {
    let mut config_map = HashMap::new();

    for line in config_module.lines() {
        if let Some(const_def) = line.strip_prefix("const ") {
            let parts: Vec<&str> = const_def.split(":").collect();
            if parts.len() == 2 {
                let name = parts[0].trim();
                let value = parts[1].trim().trim_end_matches(';').trim();
                config_map.insert(name.to_string(), value.to_string());
            }
        }
    }

    config_map
}
```

The `parse_configuration` function iterates through each line of the configuration module, checks if it starts with "const ", and then extracts the constant name and value. It then populates a HashMap with the constant names as keys and their corresponding values as values. The resulting map is returned as the output.

