```rust
fn format_text(
    text: &str,
    tabstop: usize,
    container_width: usize,
    no_hscroll: bool,
    shift: usize,
    full_width: usize,
    hscroll_offset: usize,
) -> String {
    // Apply tab stops
    let mut formatted_text = String::new();
    let mut current_width = 0;
    for c in text.chars() {
        match c {
            '\t' => {
                let spaces_to_add = tabstop - (current_width % tabstop);
                formatted_text.push_str(&" ".repeat(spaces_to_add));
                current_width += spaces_to_add;
            }
            _ => {
                formatted_text.push(c);
                current_width += 1;
            }
        }
    }

    // Apply container width and horizontal scrolling
    if no_hscroll {
        formatted_text = formatted_text.chars().take(container_width).collect();
    } else {
        formatted_text = formatted_text.chars().skip(hscroll_offset).take(container_width).collect();
    }

    // Apply horizontal shift
    if !no_hscroll {
        formatted_text = format!("{:width$}", formatted_text, width = container_width + shift);
    }

    formatted_text
}
```

This solution defines a function `format_text` that takes the input parameters and processes the text according to the given formatting requirements. It handles tab stops, container width, horizontal scrolling, text width, and horizontal scrolling offset to produce the formatted output.

