// Implementation of the ConnectivityManager module
struct ConnectivityManager {
    nodes: Vec<String>,
    connections: Vec<(String, String)>,
}

impl ConnectivityManager {
    fn new(seed_pubkeys: Vec<&str>) -> Self {
        ConnectivityManager {
            nodes: seed_pubkeys.iter().map(|&s| s.to_string()).collect(),
            connections: Vec::new(),
        }
    }

    fn add_node(&mut self, pubkey: &str) {
        self.nodes.push(pubkey.to_string());
    }

    fn establish_connection(&mut self, pubkey1: &str, pubkey2: &str) {
        self.connections.push((pubkey1.to_string(), pubkey2.to_string()));
    }

    fn get_connected_nodes(&self, pubkey: &str) -> Vec<String> {
        self.connections
            .iter()
            .filter_map(|(pub1, pub2)| {
                if pub1 == pubkey {
                    Some(pub2.clone())
                } else if pub2 == pubkey {
                    Some(pub1.clone())
                } else {
                    None
                }
            })
            .collect()
    }
}

fn main() {
    let seed_pubkeys = vec!["pubkey1", "pubkey2", "pubkey3"];
    let mut connectivity_manager = ConnectivityManager::new(seed_pubkeys.clone());

    connectivity_manager.add_node("new_pubkey");
    connectivity_manager.establish_connection("pubkey1", "new_pubkey");

    let connected_nodes = connectivity_manager.get_connected_nodes("new_pubkey");
    println!("Connected nodes for new_pubkey: {:?}", connected_nodes);
}
