use cursive::event::{Event, Key, MouseEvent, MouseButton};
use cursive::Printer;
use cursive::view::{View, ViewWrapper};
use cursive::theme::ColorStyle;
use cursive::event::EventResult;

struct List {
    items: Vec<String>,
    selected_index: usize,
}

impl List {
    fn new(items: Vec<String>) -> Self {
        List {
            items,
            selected_index: 0,
        }
    }

    fn draw_internal(&self, printer: &Printer) {
        for (i, item) in self.items.iter().enumerate() {
            let style = if i == self.selected_index {
                ColorStyle::highlight()
            } else {
                ColorStyle::primary()
            };
            printer.with_color(style, |printer| {
                printer.print((0, i), item);
            });
        }
    }

    fn select(&mut self) {
        // Handle item selection
        // For example, print the selected item to the console
        println!("Selected item: {}", self.items[self.selected_index]);
    }
}

impl View for List {
    fn draw(&self, printer: &Printer) {
        self.draw_internal(printer);
    }

    fn on_event(&mut self, event: Event) -> EventResult {
        match event {
            Event::Key(Key::Up) => {
                if self.selected_index > 0 {
                    self.selected_index -= 1;
                }
            }
            Event::Key(Key::Down) => {
                if self.selected_index < self.items.len() - 1 {
                    self.selected_index += 1;
                }
            }
            Event::Key(Key::Enter) | Event::Char(' ') => self.select(),
            Event::Mouse {
                event: MouseEvent::Release(MouseButton::Left),
                position,
                offset,
            } => {
                if position.y >= offset.y && position.y < offset.y + self.items.len() as i32 {
                    self.selected_index = (position.y - offset.y) as usize;
                    self.select();
                }
            }
            _ => {}
        }
        EventResult::Consumed(None)
    }
}
```

