```rust
struct Node {
    value: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

impl Node {
    fn new(value: i32) -> Self {
        Node {
            value,
            left: None,
            right: None,
        }
    }
}

pub struct BinaryTree {
    root: Option<Box<Node>>,
}

impl BinaryTree {
    pub fn new() -> Self {
        BinaryTree { root: None }
    }

    pub fn insert(&mut self, value: i32) {
        if let Some(ref mut node) = self.root {
            if value <= node.value {
                if let Some(ref mut left) = node.left {
                    left.insert(value);
                } else {
                    node.left = Some(Box::new(Node::new(value)));
                }
            } else {
                if let Some(ref mut right) = node.right {
                    right.insert(value);
                } else {
                    node.right = Some(Box::new(Node::new(value)));
                }
            }
        } else {
            self.root = Some(Box::new(Node::new(value)));
        }
    }

    pub fn search(&self, value: i32) -> bool {
        let mut current = &self.root;
        while let Some(node) = current {
            if value == node.value {
                return true;
            } else if value < node.value {
                current = &node.left;
            } else {
                current = &node.right;
            }
        }
        false
    }

    pub fn in_order_traversal(&self) -> Vec<i32> {
        let mut result = Vec::new();
        self.in_order_traversal_helper(&self.root, &mut result);
        result
    }

    fn in_order_traversal_helper(&self, node: &Option<Box<Node>>, result: &mut Vec<i32>) {
        if let Some(ref n) = *node {
            self.in_order_traversal_helper(&n.left, result);
            result.push(n.value);
            self.in_order_traversal_helper(&n.right, result);
        }
    }

    pub fn get_value_at_index(&self, index: usize) -> Option<i32> {
        let mut result = Vec::new();
        self.in_order_traversal_helper(&self.root, &mut result);
        result.get(index).cloned()
    }
}
