fn capitalize_words(input: &str) -> String {
    input.split_whitespace()
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                None => String::new(),
                Some(first_char) => first_char.to_uppercase()
                    .chain(chars)
                    .collect::<String>(),
            }
        })
        .collect::<Vec<String>>()
        .join(" ")
}

