use crypto::des::ecb_decrypt;
use crypto::blockmodes::PkcsPadding;
use crypto::symmetriccipher::BlockEncryptor;
use crypto::symmetriccipher::BlockDecryptor;

pub fn encrypt(message: &str, key: &str) -> String {
    let des_key = key.as_bytes();
    let des_message = message.as_bytes();

    let mut encrypted = vec![0; des_message.len() + 8 - (des_message.len() % 8)];
    let mut encryptor = ecb_encryptor(crypto::des::Des::new(des_key), PkcsPadding);
    encryptor.encrypt_block(des_message, &mut encrypted);

