pub fn decrypt(message: &str, key: &str) -> Result<String, &'static str> {
    let des_key = key.as_bytes();
    let encrypted_bytes = match base64::decode(message) {
        Ok(bytes) => bytes,
        Err(_) => return Err("Invalid base64 encoding"),
    };

    if encrypted_bytes.len() % 8 != 0 {
        return Err("Invalid encrypted message length");
