    let mut decrypted = vec![0; encrypted_bytes.len()];
    let mut decryptor = ecb_decryptor(crypto::des::Des::new(des_key), PkcsPadding);
    decryptor.decrypt_block(&encrypted_bytes, &mut decrypted);

    String::from_utf8(decrypted).map_err(|_| "Invalid UTF-8 encoding")
}
