```rust
struct Shape {
    id: u32,
    width: u32,
    height: u32,
}

impl Shape {
    fn new(id: u32, width: u32, height: u32) -> Shape {
        Shape { id, width, height }
    }
}

struct ShapeCollection {
    shapes: Vec<Shape>,
}

impl ShapeCollection {
    fn new() -> ShapeCollection {
        ShapeCollection { shapes: Vec::new() }
    }

    fn add_shape(&mut self, shape: Shape) {
        self.shapes.push(shape);
    }

    fn get_dimensions(&self, id: u32) -> Option<(u32, u32)> {
        for shape in &self.shapes {
            if shape.id == id {
                return Some((shape.width, shape.height));
            }
        }
        None
    }

    fn calculate_total_area(&self) -> u32 {
        self.shapes.iter().map(|shape| shape.width * shape.height).sum()
    }
}
