use std::env;

enum ArgType {
    Flag,
    Option,
    Positional,
}

struct Argument {
    arg_type: ArgType,
    name: String,
    value: Option<String>,
}

struct ArgumentParser {
    description: String,
    arguments: Vec<Argument>,
}

impl ArgumentParser {
    fn new() -> ArgumentParser {
        ArgumentParser {
            description: String::new(),
            arguments: Vec::new(),
        }
    }

    fn set_description(&mut self, description: &str) {
        self.description = description.to_string();
    }

    fn add_argument(&mut self, name: &str, arg_type: ArgType, description: &str) {
        self.arguments.push(Argument {
            arg_type,
            name: name.to_string(),
            value: None,
        });
    }

    fn parse_arguments(&mut self, args: Vec<String>) {
        let mut iter = args.iter().peekable();
        while let Some(arg) = iter.next() {
            match arg.as_str() {
                "-h" | "--help" => {
                    println!("{}", self.description);
                    return;
                }
                _ => {
                    if let Some(argument) = self.arguments.iter_mut().find(|a| a.name == *arg) {
                        match argument.arg_type {
                            ArgType::Flag => {
                                argument.value = Some("true".to_string());
                            }
                            ArgType::Option => {
                                if let Some(val) = iter.next() {
                                    argument.value = Some(val.to_string());
                                } else {
                                    println!("Error: Missing value for option {}", argument.name);
                                    return;
                                }
                            }
                            ArgType::Positional => {
                                argument.value = Some(arg.to_string());
                            }
                        }
                    } else {
                        println!("Error: Unknown argument {}", arg);
                        return;
                    }
                }
            }
        }
    }
}

fn main() {
    let mut args = ArgumentParser::new();
    args.set_description("Example argument parser.");
    args.add_argument("verbose", ArgType::Flag, "Enable verbose mode");
    args.add_argument("output", ArgType::Option, "Specify output file");
    args.add_argument("input", ArgType::Positional, "Input file");

    let command_line_args: Vec<String> = env::args().skip(1).collect();
    args.parse_arguments(command_line_args);
}
