use quick_xml::events::{BytesEnd, BytesText, Event};
use quick_xml::Writer;
use std::io::Cursor;

fn generate_xml(root: &str, lang: &str, value: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut write_buf = Vec::new();
    let mut writer = Writer::new(&mut write_buf);
    let mut root = quick_xml::events::BytesStart::borrowed(root.as_bytes(), root.len());

    root.push_attribute(("xml:lang", lang.as_ref()));
    writer.write_event(Event::Start(root.clone()))?;
    writer.write_event(Event::Text(BytesText::from_plain_str(value)))?;
    writer.write_event(Event::End(BytesEnd::borrowed(root.name())))?;
    Ok(String::from_utf8(write_buf)?)
}
```

