#[derive(Debug, PartialEq)]
enum Token {
    Number(i32),
    Plus,
    Minus,
    Mul,
    Div,
    LeftParen,
    RightParen,
}

fn tokenize_expression(expression: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut iter = expression.chars().peekable();

    while let Some(&c) = iter.peek() {
        match c {
            '0'..='9' => {
                let mut number = String::new();
                while let Some(&c) = iter.peek() {
                    if c.is_digit(10) {
                        number.push(c);
                        iter.next();
                    } else {
                        break;
                    }
                }
                tokens.push(Token::Number(number.parse().unwrap()));
            }
            '+' => {
                tokens.push(Token::Plus);
                iter.next();
            }
            '-' => {
                tokens.push(Token::Minus);
                iter.next();
            }
            '*' => {
                tokens.push(Token::Mul);
                iter.next();
            }
            '/' => {
                tokens.push(Token::Div);
                iter.next();
            }
            '(' => {
                tokens.push(Token::LeftParen);
                iter.next();
            }
            ')' => {
                tokens.push(Token::RightParen);
                iter.next();
            }
            _ => {
                iter.next();
            }
        }
    }

    tokens
}

fn main() {
    let expression = "3 + 4 * (2 - 1)";
    let tokens = tokenize_expression(expression);
    println!("{:?}", tokens);
}
```

In this solution, the `tokenize_expression` function iterates through the characters of the input expression, identifying and creating tokens based on the encountered characters. It handles numbers, operators, and parentheses, while ignoring whitespace characters. The resulting tokens are stored in a vector and returned as the output.

