use std::path::{Path, PathBuf};
use std::fs;
use std::io::{Write, Read};
use std::fs::File;

struct FileBundler {
    files: Vec<PathBuf>,
    bundle_dir: PathBuf,
}

impl FileBundler {
    fn new(bundle_dir: PathBuf) -> FileBundler {
        FileBundler {
            files: Vec::new(),
            bundle_dir,
        }
    }
}

impl Bundler for FileBundler {
    fn add_file(&mut self, file: PathBuf) {
        self.files.push(file);
    }

    fn bundle_files(&self) -> PathBuf {
        let mut bundle_content = Vec::new();
        for file in &self.files {
            let mut file_content = Vec::new();
            let mut file = File::open(file).expect("Unable to open file");
            file.read_to_end(&mut file_content).expect("Unable to read file content");
            bundle_content.extend_from_slice(&file_content);
        }

        let bundle_path = self.bundle_dir.join("bundle.txt");
        let mut bundle_file = File::create(&bundle_path).expect("Unable to create bundle file");
        bundle_file.write_all(&bundle_content).expect("Unable to write bundle content");

        bundle_path
    }

    fn bundle_location(&self) -> PathBuf {
        self.bundle_dir.clone()
    }

    fn clone_bundler(&self) -> Box<dyn Bundler> {
        Box::new(FileBundler {
            files: self.files.clone(),
            bundle_dir: self.bundle_dir.clone(),
        })
    }
}

fn main() {
    let bundle_dir = PathBuf::from("/path/to/bundle");
    let mut bundler = FileBundler::new(bundle_dir.clone());

    bundler.add_file(PathBuf::from("/path/to/file1.txt"));
    bundler.add_file(PathBuf::from("/path/to/file2.txt"));

    let bundle_location = bundler.bundle_files();
    println!("Bundle created at: {:?}", bundle_location);

    let cloned_bundler = bundler.clone_bundler();
    cloned_bundler.add_file(PathBuf::from("/path/to/file3.txt"));

    let cloned_bundle_location = cloned_bundler.bundle_files();
    println!("Cloned bundle created at: {:?}", cloned_bundle_location);
}
```

