use std::fs::File;
use std::io::{Read, Result};
use std::convert::TryInto;

#[derive(Debug)]
enum FitFieldData {
    FitU8z(Vec<u8>),
    FitU16z(Vec<u16>),
}

#[derive(Debug)]
enum FitError {
    IoError(std::io::Error),
    InvalidDataType,
}

fn process_fit_data(file_path: &str) -> Result<FitFieldData, FitError> {
    let mut file = File::open(file_path).map_err(|e| FitError::IoError(e))?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer).map_err(|e| FitError::IoError(e))?;

    // Process FitU8z data
    let fit_u8z_data = buffer.chunks_exact(1).map(|chunk| chunk[0]).collect();
    let fit_u8z_result = FitFieldData::FitU8z(fit_u8z_data);

    // Process FitU16z data
    let fit_u16z_data = buffer.chunks_exact(2).map(|chunk| u16::from_le_bytes(chunk.try_into().unwrap())).collect();
    let fit_u16z_result = FitFieldData::FitU16z(fit_u16z_data);

    // Return the appropriate result based on the data type
    match (fit_u8z_result, fit_u16z_result) {
        (FitFieldData::FitU8z(_), _) => Ok(fit_u8z_result),
        (_, FitFieldData::FitU16z(_)) => Ok(fit_u16z_result),
        _ => Err(FitError::InvalidDataType),
    }
}
```

