use std::collections::HashMap;

trait Interner<T: Eq + std::hash::Hash + Copy> {
    fn intern(&mut self, value: T) -> u32;
    fn gensym(&mut self, value: T) -> u32;
    fn get(&self, key: u32) -> Option<&T>;
    fn len(&self) -> u32;
}

struct MyInterner<T: Eq + std::hash::Hash + Copy> {
    values: HashMap<T, u32>,
    reverse_values: HashMap<u32, T>,
    counter: u32,
}

impl<T: Eq + std::hash::Hash + Copy> MyInterner<T> {
    fn new() -> Self {
        MyInterner {
            values: HashMap::new(),
            reverse_values: HashMap::new(),
            counter: 0,
        }
    }
}

impl<T: Eq + std::hash::Hash + Copy> Interner<T> for MyInterner<T> {
    fn intern(&mut self, value: T) -> u32 {
        if let Some(&key) = self.values.get(&value) {
            key
        } else {
            let key = self.counter;
            self.values.insert(value, key);
            self.reverse_values.insert(key, value);
            self.counter += 1;
            key
        }
    }

    fn gensym(&mut self, value: T) -> u32 {
        let key = self.counter;
        self.values.insert(value, key);
        self.reverse_values.insert(key, value);
        self.counter += 1;
        key
    }

    fn get(&self, key: u32) -> Option<&T> {
        self.reverse_values.get(&key)
    }

    fn len(&self) -> u32 {
        self.values.len() as u32
    }
}

fn main() {
    let mut interner = MyInterner::new();
    let key1 = interner.intern("hello");
    let key2 = interner.intern("world");
    let key3 = interner.gensym("rust");

    println!("Interned keys: {}, {}, {}", key1, key2, key3);
    println!("Interned values: {}, {}, {}", interner.get(key1).unwrap(), interner.get(key2).unwrap(), interner.get(key3).unwrap());
    println!("Number of interned values: {}", interner.len());
}
```

