/// An interned string created via [`intern!`].
///
/// [`intern!`]: macro.intern.html
#[derive(Clone, Copy)]
pub struct Str {
    /// 14-bit address
    pub(crate) address: u16,
}

struct FmtWrite<'a> {
    fmt: &'a mut InternalFormatter,
}

struct InternalFormatter {
    // Implementation details for formatting
}

struct StringInterner {
    strings: HashMap<String, u16>,
    next_address: u16,
}

impl StringInterner {
    fn new() -> Self {
        StringInterner {
            strings: HashMap::new(),
            next_address: 0,
        }
    }

    fn intern(&mut self, s: &str) -> Str {
        if let Some(&address) = self.strings.get(s) {
            Str { address }
        } else {
            let address = self.next_address;
            self.next_address += 1;
            self.strings.insert(s.to_string(), address);
            Str { address }
        }
    }

    fn get(&self, interned: Str) -> Option<String> {
        for (string, &address) in &self.strings {
            if address == interned.address {
                return Some(string.clone());
            }
        }
        None
    }

    fn write_formatted(&mut self, interned: Str, fmt_write: &mut FmtWrite) {
        if let Some(string) = self.get(interned) {
            fmt_write.fmt.write_str(&string);
        }
    }
}

fn main() {
    let mut interner = StringInterner::new();
    let interned_hello = interner.intern("hello");
    let interned_world = interner.intern("world");

    let mut formatter = InternalFormatter { /* Initialize formatter */ };
    let mut fmt_write = FmtWrite { fmt: &mut formatter };

    interner.write_formatted(interned_hello, &mut fmt_write);
    interner.write_formatted(interned_world, &mut fmt_write);
}
