fn create_data_block(table_info: Arc<TableInfo>, data_rows: Vec<Vec<Box<dyn Any>>>) -> Result<DataBlock> {
    // Validate the number of columns
    if table_info.fields().len() != data_rows.get(0).map_or(0, |row| row.len()) {
