struct BoundedVecDeque<T> {
    capacity: usize,
    front: usize,
    rear: usize,
    length: usize,
    buffer: Vec<Option<T>>,
}

impl<T> BoundedVecDeque<T> {
    fn new(capacity: usize) -> Self {
        BoundedVecDeque {
            capacity,
            front: 0,
            rear: 0,
            length: 0,
            buffer: vec![None; capacity],
        }
    }

    fn push_front(&mut self, value: T) {
        if self.length == self.capacity {
            self.pop_back();
        }
        self.front = (self.front + self.capacity - 1) % self.capacity;
        self.buffer[self.front] = Some(value);
        self.length += 1;
    }

    fn push_back(&mut self, value: T) {
        if self.length == self.capacity {
            self.pop_front();
        }
        self.buffer[self.rear] = Some(value);
        self.rear = (self.rear + 1) % self.capacity;
        self.length += 1;
    }

    fn pop_front(&mut self) -> Option<T> {
        if self.length == 0 {
            return None;
        }
        let value = self.buffer[self.front].take();
        self.front = (self.front + 1) % self.capacity;
        self.length -= 1;
        value
    }

    fn pop_back(&mut self) -> Option<T> {
        if self.length == 0 {
            return None;
        }
        self.rear = (self.rear + self.capacity - 1) % self.capacity;
        let value = self.buffer[self.rear].take();
        self.length -= 1;
        value
    }

    fn len(&self) -> usize {
        self.length
    }

    fn capacity(&self) -> usize {
        self.capacity
    }
}

fn main() {
    let mut deque: BoundedVecDeque<i32> = BoundedVecDeque::new(3);
    deque.push_back(1);
    deque.push_back(2);
    deque.push_back(3);
    deque.push_back(4);
    assert_eq!(deque.pop_front(), Some(2));
    assert_eq!(deque.pop_back(), Some(4));
    assert_eq!(deque.len(), 2);
    assert_eq!(deque.capacity(), 3);
}
```

This solution provides a complete implementation of a bounded vector deque in Rust, satisfying the requirements outlined in the problem description. The `BoundedVecDeque` struct maintains the bounded nature of the deque by removing the oldest elements when the capacity is reached. The methods for adding, removing, and querying elements ensure the correct behavior of the data structure.

