use std::net::SocketAddr;
use tokio::net::UdpSocket as TokioUdpSocket;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

pub struct UdpSocket {
    udp_listener: AsyncFd<i32>,
}

impl UdpSocket {
    pub fn new(udp_listener: AsyncFd<i32>) -> UdpSocket {
        UdpSocket { udp_listener }
    }

    pub async fn recv_from(&self, buf: &mut [u8]) -> Result<(usize, SocketAddr), std::io::Error> {
        let mut guard = self.udp_listener.readable().await?;
        let mut udp_socket = unsafe { TokioUdpSocket::from_std(std::net::UdpSocket::from_raw_fd(guard.get_ref())) };
        let (size, src) = udp_socket.recv_from(buf).await?;
        Ok((size, src))
    }

    pub async fn send_to(&self, buf: &[u8], target: &SocketAddr) -> Result<usize, std::io::Error> {
        let mut guard = self.udp_listener.writable().await?;
        let mut udp_socket = unsafe { TokioUdpSocket::from_std(std::net::UdpSocket::from_raw_fd(guard.get_ref())) };
        let size = udp_socket.send_to(buf, target).await?;
        Ok(size)
    }
}
```

In the solution, we implement the `UdpSocket` struct with the required methods using the Tokio framework. The `new` method initializes the `UdpSocket` instance, and the `recv_from` and `send_to` methods handle asynchronous receiving and sending of UDP datagrams, respectively. The solution demonstrates the use of Tokio's asynchronous I/O operations for UDP socket communication.

