use nom::{
    IResult,
    bytes::complete::{tag, take_while},
    combinator::map_res,
    sequence::tuple,
};

// Parser for the version token
fn version(input: LocatedSpan<&[u8]>) -> IResult<LocatedSpan<&[u8]>, (u8, u8)> {
    let (input, _) = tag("%PDF-")(input)?;
    let (input, major) = map_res(take_while(|c: u8| c.is_ascii_digit()), |s: LocatedSpan<&[u8]>| {
        std::str::from_utf8(s.fragment())
            .unwrap()
            .parse::<u8>()
            .map_err(|_| nom::Err::Error(nom::error::Error::new(s, nom::error::ErrorKind::Digit)))
    })(input)?;
    let (input, _) = tag(".")(input)?;
    let (input, minor) = map_res(take_while(|c: u8| c.is_ascii_digit()), |s: LocatedSpan<&[u8]>| {
        std::str::from_utf8(s.fragment())
            .unwrap()
            .parse::<u8>()
            .map_err(|_| nom::Err::Error(nom::error::Error::new(s, nom::error::ErrorKind::Digit)))
    })(input)?;

    Ok((input, (major, minor)))
}

// Parser for the binary indicator token
fn binary_indicator(input: LocatedSpan<&[u8]>) -> IResult<LocatedSpan<&[u8]>, bool> {
    let (input, _) = tag("%\xbf\xbf\xbf\xbf\xbf\n")(input)?;
    Ok((input, true))
}
```

In the solution, we use the `nom` parser combinator library to implement the parsers for the version and binary indicator tokens. The `version` function uses parser combinators to match the specific structure of the version token and extract the major and minor version numbers. The `binary_indicator` function similarly matches the structure of the binary indicator token and returns a boolean indicating the presence of a binary file. The parsers are designed to handle the specific byte sequences and extract the required information from the input tokens.

