// basic_life.rs

#[derive(Clone, Copy, PartialEq)]
pub enum CellState {
    Dead,
    Alive,
}

pub struct Cell {
    state: CellState,
}

impl Cell {
    pub fn new(state: CellState) -> Cell {
        Cell { state }
    }
}

pub struct Grid {
    cells: Vec<Vec<Cell>>,
    rows: usize,
    cols: usize,
}

impl Grid {
    pub fn new(rows: usize, cols: usize) -> Grid {
        let cells = vec![vec![Cell::new(CellState::Dead); cols]; rows];
        Grid {
            cells,
            rows,
            cols,
        }
    }

    pub fn set_cell_state(&mut self, row: usize, col: usize, state: CellState) {
        self.cells[row][col] = Cell::new(state);
    }

    pub fn get_cell_state(&self, row: usize, col: usize) -> CellState {
        self.cells[row][col].state
    }

    pub fn progress_generation(&mut self) {
        let mut next_gen = self.cells.clone();

        for i in 0..self.rows {
            for j in 0..self.cols {
                let live_neighbors = self.count_live_neighbors(i, j);
                match (self.cells[i][j].state, live_neighbors) {
                    (CellState::Alive, 2..=3) => next_gen[i][j].state = CellState::Alive,
                    (CellState::Dead, 3) => next_gen[i][j].state = CellState::Alive,
                    _ => next_gen[i][j].state = CellState::Dead,
                }
            }
        }

        self.cells = next_gen;
    }

    fn count_live_neighbors(&self, row: usize, col: usize) -> usize {
        let mut live_count = 0;
        for i in (row as isize - 1)..=(row as isize + 1) {
            for j in (col as isize - 1)..=(col as isize + 1) {
                if i >= 0 && i < self.rows as isize && j >= 0 && j < self.cols as isize
                    && !(i as usize == row && j as usize == col)
                {
                    if self.cells[i as usize][j as usize].state == CellState::Alive {
                        live_count += 1;
                    }
                }
            }
        }
        live_count
    }
}
