fn schedule_write_requests(requests: Vec<(i32, i32, i32)>) -> Vec<i32> {
    let mut scheduled_order: Vec<i32> = Vec::new();
    let mut current_offset: i32 = 0;

    let mut grouped_requests: std::collections::HashMap<i32, Vec<(i32, i32)>> = std::collections::HashMap::new();

    for (fd, buf, offset) in requests {
        if !grouped_requests.contains_key(&fd) {
            grouped_requests.insert(fd, Vec::new());
        }
        grouped_requests.get_mut(&fd).unwrap().push((buf, offset));
    }

    for (_, reqs) in grouped_requests {
        reqs.sort_by_key(|&(_, offset)| offset);
        for (buf, offset) in reqs {
            scheduled_order.push(current_offset);
            current_offset = offset;
        }
    }

    scheduled_order
}
```

