struct CustomToken {
    balances: std::collections::BTreeMap<AccountId, U256>,
}

impl CustomToken {
    // Function to transfer tokens from sender to recipient
    fn transfer(&mut self, sender: AccountId, recipient: AccountId, amount: U256) -> Result<(), ApiError> {
        // Ensure sender has sufficient balance
        let sender_balance = self.balances.get(&sender).copied().unwrap_or_default();
        if sender_balance < amount {
            return Err(ApiError::User(1)); // Insufficient balance error
        }

        // Deduct the transferred amount from sender's balance
        self.balances.insert(sender, sender_balance - amount);

        // Add the transferred amount to recipient's balance
        let recipient_balance = self.balances.get(&recipient).copied().unwrap_or_default();
        self.balances.insert(recipient, recipient_balance + amount);

        Ok(()) // Token transfer successful
    }
}

