pub struct KeyValueStore {
    store: std::collections::HashMap<String, Vec<u8>>,
}

impl KeyValueStore {
    pub fn new() -> Self {
        KeyValueStore {
            store: std::collections::HashMap::new(),
        }
    }

    pub fn put(&mut self, key: String, data: Vec<u8>, compressor: Option<&dyn Compressor>) {
        let compressed_data = match compressor {
            Some(c) => c.compress(&data),
            None => data,
        };
        self.store.insert(key, compressed_data);
    }

    pub fn get(&self, key: &str, compressor: Option<&dyn Compressor>) -> Option<Vec<u8>> {
        if let Some(data) = self.store.get(key) {
            match compressor {
                Some(c) => Some(c.decompress(data)),
                None => Some(data.clone()),
            }
        } else {
            None
        }
    }
}
```

