#[cfg(feature = "iterator")]
use std::collections::HashMap;
#[cfg(feature = "iterator")]
use std::ops::{Bound, RangeBounds};

#[cfg(feature = "iterator")]
use cosmwasm_std::{Order, Record};

#[cfg(feature = "iterator")]
struct CustomHashMapIterator<'a, K, V> {
    map: &'a HashMap<K, V>,
    range: (Bound<&'a K>, Bound<&'a K>),
    order: Order,
    current_key: Option<&'a K>,
}

#[cfg(feature = "iterator")]
impl<'a, K, V> Iterator for CustomHashMapIterator<'a, K, V>
where
    K: Ord,
{
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        match self.current_key {
            Some(key) => {
                let next_key = match self.order {
                    Order::Ascending => self.map.range((Bound::Excluded(key), Bound::Unbounded)).next().map(|(k, _)| k),
                    Order::Descending => self.map.range((Bound::Unbounded, Bound::Excluded(key))).next_back().map(|(k, _)| k),
                };
                self.current_key = next_key;
                next_key.map(|k| (k, self.map.get(k).unwrap()))
            }
            None => None,
        }
    }
}

#[cfg(feature = "iterator")]
fn main() {
    let mut map = HashMap::new();
    map.insert("a", 1);
    map.insert("b", 2);
    map.insert("c", 3);

    let iterator = CustomHashMapIterator {
        map: &map,
        range: (Bound::Included(&"a"), Bound::Excluded(&"c")),
        order: Order::Ascending,
        current_key: Some(&"a"),
    };

    for (key, value) in iterator {
        println!("Key: {}, Value: {}", key, value);
    }
}
```

In the provided solution, a custom iterator `CustomHashMapIterator` is implemented for the HashMap data structure. The iterator supports generic key and value types and allows iterating over the key-value pairs within a specified range and order. The `next` method of the iterator is implemented to handle both ascending and descending orders based on the specified range. Finally, a sample usage of the custom iterator is demonstrated in the `main` function.

