fn process_intcode(program: &str) -> i32 {
    let mut intcode: Vec<i32> = program
        .split(',')
        .map(|x| x.parse().unwrap())
        .collect();

    let mut i = 0;
    loop {
        match intcode[i] {
            1 => {
                let pos1 = intcode[i + 1] as usize;
                let pos2 = intcode[i + 2] as usize;
                let pos3 = intcode[i + 3] as usize;
                intcode[pos3] = intcode[pos1] + intcode[pos2];
                i += 4;
            }
            2 => {
                let pos1 = intcode[i + 1] as usize;
                let pos2 = intcode[i + 2] as usize;
                let pos3 = intcode[i + 3] as usize;
                intcode[pos3] = intcode[pos1] * intcode[pos2];
                i += 4;
            }
            99 => break,
            _ => panic!("Invalid opcode"),
        }
    }
    intcode[0]
}
```

