pub struct JsonResponse<T, E>
where
    T: Serialize + Entity + Send,
{
    data: T,
    cookies: Option<Vec<String>>,
}

impl<T, E> JsonResponse<T, E>
where
    T: Serialize + Entity + Send,
{
    pub fn new(data: T) -> Self {
        JsonResponse {
            data,
            cookies: None,
        }
    }

    pub fn with_cookies(mut self, cookies: Vec<String>) -> Self {
        self.cookies = Some(cookies);
        self
    }

    pub fn into_response(self) -> Response<Body> {
        let mut response = Response::new(Body::empty());
        let json_data = serde_json::to_string(&self.data).unwrap();
        *response.body_mut() = json_data.into();

        if let Some(cookies) = self.cookies {
            for cookie in cookies {
                response.headers_mut().insert(
                    SET_COOKIE,
                    HeaderValue::from_str(&cookie).unwrap(),
                );
            }
        }

        response
    }
}
