fn dictionary_stats(dictionary_path: &str) -> DictionaryStats {
    let file = File::open(dictionary_path).expect("Failed to open file");
    let reader = BufReader::new(file);

    let mut total_words = 0;
    let mut longest_word = String::new();
    let mut total_length = 0;
    let mut words_with_z = 0;

    for line in reader.lines() {
        if let Ok(word) = line {
            total_words += 1;
            total_length += word.len();
            if word.len() > longest_word.len() {
                longest_word = word.clone();
            }
            if word.contains('z') {
                words_with_z += 1;
            }
        }
    }

    let average_length = total_length as f64 / total_words as f64;

    DictionaryStats {
        total_words,
        longest_word,
        average_length,
        words_with_z,
    }
}

fn main() {
