```rust
use std::path::PathBuf;

struct FileSystem {
    destination: PathBuf,
}

impl FileSystem {
    fn new() -> FileSystem {
        FileSystem {
            destination: PathBuf::from("/"),
        }
    }

    fn change_directory(&mut self, path: &str) {
        let mut new_path = self.destination.clone();
        new_path.push(path);
        if new_path.exists() && new_path.is_dir() {
            self.destination = new_path;
        }
    }

    fn current_directory(&self) -> String {
        self.destination.to_string_lossy().to_string()
    }
}

fn main() {
    let mut fs = FileSystem::new();
    fs.change_directory("documents");
    println!("{}", fs.current_directory()); // Output: /documents
    fs.change_directory("/photos");
    println!("{}", fs.current_directory()); // Output: /photos
    fs.change_directory("../music");
    println!("{}", fs.current_directory()); // Output: /music
