use std::fs::File;
use std::io::prelude::*;
use std::error::Error;
use nes::Cartridge;

fn read_cartridge(path: &str) -> Result<Cartridge, Box<dyn Error>> {
    let mut file = File::open(path)?;

    // Read the header information
    let mut header = [0u8; 16];
    file.read_exact(&mut header)?;

    // Extract necessary data from the header
    let prg_rom_size = header[4] as usize * 16 * 1024;
    let chr_rom_size = header[5] as usize * 8 * 1024;
    let mapper = (header[6] >> 4) | (header[7] & 0xF0);

    // Read the program ROM data
    let mut prg_rom = vec![0u8; prg_rom_size];
    file.read_exact(&mut prg_rom)?;

    // Read the character ROM data
    let mut chr_rom = vec![0u8; chr_rom_size];
    file.read_exact(&mut chr_rom)?;

    Ok(Cartridge {
        prg_rom,
        chr_rom,
        mapper,
    })
}
```
In the solution, the `read_cartridge` function opens the file at the given path and reads the necessary data to construct a `Cartridge` instance. It first reads the header information to extract the sizes of the program ROM and character ROM, as well as the mapper type. Then, it reads the program ROM and character ROM data into vectors. If any errors occur during file reading or data extraction, the function returns a `Result` with an appropriate error message.

