use num_bigint::BigUint;
use num_traits::{One, Zero};
use sha2::{Digest, Sha256};

fn key_generation(p: &BigUint, g: &BigUint, x: &BigUint) -> BigUint {
    g.modpow(x, p)
}

fn signature_generation(p: &BigUint, g: &BigUint, x: &BigUint, m: &str) -> (BigUint, BigUint) {
    let k = BigUint::from(12345u32); // Replace with actual random value generation
    let r = g.modpow(&k, p);
    let e = hash_concat(&r, m);
    let s = (k - x * e) % (p - BigUint::one());
    (r, s)
}

fn hash_concat(r: &BigUint, m: &str) -> BigUint {
    let mut hasher = Sha256::new();
    hasher.update(r.to_bytes_be());
    hasher.update(m.as_bytes());
    BigUint::from_bytes_be(&hasher.finalize())
}

fn main() {
    let p = BigUint::from(23u32);
    let g = BigUint::from(5u32);
    let x = BigUint::from(6u32);
    let m = "Hello, Schnorr!";

    let y = key_generation(&p, &g, &x);
    let (r, s) = signature_generation(&p, &g, &x, m);

    println!("Public Key (y): {}", y);
    println!("Signature (r, s): ({}, {})", r, s);
}
