use rand::seq::SliceRandom;

#[derive(Debug)]
pub struct RandomSubset {
    limit: u32,
}

impl RandomSubset {
    pub fn new(limit: u32) -> Self {
        RandomSubset { limit }
    }

    pub fn get_random_subset<T>(&self, elements: &[T]) -> Vec<&T> {
        let mut rng = rand::thread_rng();
        let mut subset: Vec<&T> = elements.iter().collect();
        subset.shuffle(&mut rng);
