fn validate_passport_data(passport: &str) -> bool {
    let fields: Vec<(&str, &str)> = passport.split_whitespace()
        .map(|s| {
            let mut iter = s.split(':');
            (iter.next().unwrap(), iter.next().unwrap())
        })
        .collect();

    let mut valid = true;
    for field in fields {
        valid &= match field.0 {
            "byr" => {
                let byr: u32 = field.1.parse().unwrap();
                byr >= 1920 && byr <= 2002
            }
            "iyr" => {
                let iyr: u32 = field.1.parse().unwrap();
                iyr >= 2010 && iyr <= 2020
            }
            "eyr" => {
                let eyr: u32 = field.1.parse().unwrap();
                eyr >= 2020 && eyr <= 2030
            }
            "hgt" => {
                if field.1.ends_with("cm") {
                    let hgt: u32 = field.1.trim_end_matches("cm").parse().unwrap();
                    hgt >= 150 && hgt <= 193
                } else if field.1.ends_with("in") {
                    let hgt: u32 = field.1.trim_end_matches("in").parse().unwrap();
                    hgt >= 59 && hgt <= 76
                } else {
                    false
                }
            }
            "hcl" => {
                let re = regex::Regex::new(r"^#[0-9a-fA-F]{6}$").unwrap();
                re.is_match(field.1)
            }
            "ecl" => {
                matches!(field.1, "amb" | "blu" | "brn" | "gry" | "grn" | "hzl" | "oth")
            }
            "pid" => {
                let re = regex::Regex::new(r"^\d{9}$").unwrap();
                re.is_match(field.1)
            }
            "cid" => true,
            _ => false,
        };
    }
    valid
}
