macro_rules! double_expr {
    // Base case: for literal values
    ($val:literal) => {
        $val * 2
    };
    // Case for binary operations
    ($left:expr + $right:expr) => {
        double_expr!($left) + double_expr!($right)
    };
    ($left:expr - $right:expr) => {
        double_expr!($left) - double_expr!($right)
    };
    ($left:expr * $right:expr) => {
        double_expr!($left) * double_expr!($right)
    };
    ($left:expr / $right:expr) => {
        double_expr!($left) / double_expr!($right)
    };
    // Case for function calls
    ($func:ident($($arg:tt),*)) => {
        $func(double_expr!($($arg),*))
    };
    // Case for variable references
    ($var:ident) => {
        $var * 2
    };
}

fn main() {
    let x = 5;
    println!("{}", double_expr!(5)); // Output: 10
    println!("{}", double_expr!(x + 3)); // Output: x + 3 + x + 3
    println!("{}", double_expr!(add(2, 3))); // Output: add(2, 3) + add(2, 3)
}
