use nom::{IResult, bytes::complete::{tag, take_while_m_n}, number::complete::be_u64, combinator::map_res};
use std::fs::File;
use std::io::Read;

pub struct EBMLHeader {
    pub read_version: u64,
    pub max_id_length: u64,
    pub max_size_length: u64,
    pub doc_type: String,
    pub doc_type_version: u64,
    pub doc_type_read_version: u64,
}

fn ebml_varint(input: &[u8]) -> IResult<&[u8], u64> {
    map_res(take_while_m_n(1, 8, |b| (b & 0x80) != 0), |bytes: &[u8]| {
        let mut value = 0;
        for &byte in bytes {
            value = (value << 7) | (byte & 0x7F) as u64;
        }
        Ok(value)
    })(input)
}

fn ebml_string(input: &[u8]) -> IResult<&[u8], &[u8]> {
    let (input, length) = ebml_varint(input)?;
    take_while_m_n(0, length as usize, |b| b != 0)(input)
}

fn parse_ebml_header(file_path: &str) -> Result<EBMLHeader, std::io::Error> {
    let mut file = File::open(file_path)?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer)?;

    match ebml_header(&buffer) {
        Ok((_, header)) => Ok(header),
        Err(_) => Err(std::io::Error::new(std::io::ErrorKind::InvalidData, "Failed to parse EBML header")),
    }
}
```

