```rust
use std::time::{Instant, Duration};

struct RateLimiter {
    op_limit: u32,
    window_duration: Duration,
    last_reset: Instant,
    count: u32,
}

impl RateLimiter {
    fn new(op_limit: u32, window_duration: Duration) -> Self {
        RateLimiter {
            op_limit,
            window_duration,
            last_reset: Instant::now(),
            count: 0,
        }
    }

    fn allow(&mut self) -> bool {
        let now = Instant::now();
        if now.duration_since(self.last_reset) > self.window_duration {
            self.last_reset = now;
            self.count = 1;
            true
        } else if self.count < self.op_limit {
            self.count += 1;
            true
        } else {
            false
        }
    }
}

fn main() {
    let mut limiter = RateLimiter::new(5, Duration::from_secs(10));
    for _ in 0..7 {
        println!("Operation allowed: {}", limiter.allow());
    }
}
