struct PortCell<T> {
    value: RefCell<T>,
    downstreams: RefCell<Vec<Rc<Port<T>>>>,
}

impl<T> PortCell<T> {
    fn new(value: T) -> Self {
        PortCell {
            value: RefCell::new(value),
            downstreams: RefCell::new(Vec::new()),
        }
    }
}

struct Port<T> {
    cell: Rc<PortCell<T>>,
}

impl<T> Port<T> {
    fn new(value: T) -> Self {
        let cell = Rc::new(PortCell::new(value));
        Port { cell }
    }

    fn set_upstream(&self, new_binding: Rc<PortCell<T>>) {
        for downstream in self.cell.downstreams.borrow().iter() {
            let mut downstream_mut = downstream.cell.borrow_mut();
            *downstream_mut = new_binding.clone();
        }
    }
}

fn main() {
    let port1 = Port::new(10);
    let port2 = Port::new(20);
    let port3 = Port::new(30);

    port1.cell.borrow_mut().downstreams.borrow_mut().push(port2.cell.clone());
    port1.cell.borrow_mut().downstreams.borrow_mut().push(port3.cell.clone());

    let new_binding = Rc::new(PortCell::new(100));
    port1.set_upstream(new_binding);

    // Now all downstream ports of port1 should point to the new_binding
    for downstream in port1.cell.borrow().downstreams.borrow().iter() {
        println!("{}", downstream.value.borrow());
    }
}
