// Define the ChannelId and Error types
struct ChannelId(u32);
struct ConversionError(String);

// Implement the conversion function
pub fn channel_id_from_bytes(channel: Vec<u8>) -> Result<ChannelId, Error> {
    if channel.len() != 4 {
        return Err(Box::new(ConversionError("Invalid byte length".to_string())));
    }

    let mut id: u32 = 0;
    for &byte in &channel {
        id = (id << 8) | byte as u32;
    }

    Ok(ChannelId(id))
}

fn main() {
    let bytes: Vec<u8> = vec![0, 1, 2, 3];
    match channel_id_from_bytes(bytes) {
        Ok(channel_id) => println!("Channel ID: {}", channel_id.0),
        Err(err) => println!("Conversion Error: {}", err.description()),
    }
}
```

