use std::cmp;

#[derive(Debug, Clone)]
struct PNCounter {
    id: u64,
    positive: u64,
    negative: u64,
}

impl PNCounter {
    fn new(id: u64) -> PNCounter {
        PNCounter {
            id,
            positive: 0,
            negative: 0,
        }
    }

    fn increment(&mut self) {
        self.positive += 1;
    }

    fn decrement(&mut self) {
        self.negative += 1;
    }

    fn value(&self) -> i64 {
        self.positive as i64 - self.negative as i64
    }

    fn merge(&mut self, other: &PNCounter) {
        self.positive = cmp::max(self.positive, other.positive);
        self.negative = cmp::max(self.negative, other.negative);
    }
}

fn main() {
    // Example usage
    let mut counter1 = PNCounter::new(1);
    counter1.increment();
    counter1.increment();
    counter1.decrement();

    let mut counter2 = PNCounter::new(2);
    counter2.increment();
    counter2.decrement();
    counter2.decrement();

    counter1.merge(&counter2);

    println!("Counter 1 value: {}", counter1.value()); // Output: Counter 1 value: 1
}
```
In this solution, we define the `PNCounter` struct with its methods to create, increment, decrement, get the value, and merge counters. The `merge` method takes the maximum positive and negative counts from the current and other counters. This implementation ensures the integrity of the counts and handles concurrent updates correctly.

