struct SmoothNumber {
    n: usize,
    numbers: Vec<f64>,
}

impl SmoothNumber {
    fn new(n: usize) -> SmoothNumber {
        SmoothNumber { n, numbers: Vec::new() }
    }

    fn put(&mut self, num: f64) {
        if self.numbers.len() == self.n {
            self.numbers.remove(0);
        }
        self.numbers.push(num);
    }

    fn get(&self) -> Result<f64, String> {
        if self.numbers.len() < self.n {
            return Err(String::from("Not enough elements for smooth average"));
        }
