async fn execute_commands(commands: Vec<String>) -> Vec<ExitStatus> {
    let env = DefaultEnvArc::new(DefaultEnvConfigArc::new());
    let mut exit_statuses = Vec::new();

    for command in commands {
        let mut args_env = env.clone();
        let command_args: Vec<&str> = command.split_whitespace().collect();
        args_env.set_arguments(command_args.iter().map(|s| s.to_string()));

