    pub fn decode(tx_packet: TxPacket<R, V>, data: &[u8]) -> Result<RxPacket<R, V>, &'static str> {
        let mut rxpacket = RxPacket(Vec::new());

        let mut command_id = tx_packet.first_command_id;
        let mut i = 0;
        for c in tx_packet.commands.iter() {
            if data.get(i) != Some(&command_id) {
                println!("Bad command ID {}", data[i]);
                return Err("Bad command ID");
            }
            let command_data = &data[i + 1..i + 1 + c.size()];
            let rx_command = RxCommand::new(command_id, command_data);
            rxpacket.0.push(rx_command);
            i += 1 + c.size();
            command_id = command_id.wrapping_add(1);
        }

        Ok(rxpacket)
    }
}
