fn parse(data: &[u8]) -> Vec<i32> {
    let mut result = Vec::new();
    let mut current_num = 0;
    let mut is_negative = false;
    let mut is_number = false;

    for &byte in data {
        if byte.is_ascii_digit() {
            current_num = current_num * 10 + (byte - b'0') as i32;
            is_number = true;
        } else if byte == b'-' && !is_number {
            is_negative = true;
        } else if byte == b',' {
            if is_negative {
                current_num = -current_num;
                is_negative = false;
            }
            result.push(current_num);
            current_num = 0;
            is_number = false;
        } else if !byte.is_ascii_whitespace() {
            // Ignore any other characters
            return Vec::new();
        }
    }

    if is_negative {
        current_num = -current_num;
    }
    if is_number {
        result.push(current_num);
    }

    result
}

