```rust
use std::collections::HashMap;

struct MerkleSparseTree<T> {
    root: Option<Box<Node<T>>>,
}

struct Node<T> {
    hash: [u8; 32],
    left: Option<Box<Node<T>>>,
    right: Option<Box<Node<T>>>,
    data: Option<T>,
}

impl<T> MerkleSparseTree<T> {
    fn new(data: Vec<Option<T>>, hash_func: &dyn Fn(&[u8]) -> [u8; 32]) -> Self {
        let mut leaves: Vec<Option<Box<Node<T>>>> = Vec::new();
        for d in data {
            let leaf = match d {
                Some(val) => Some(Box::new(Node {
                    hash: hash_func(&[val as u8]),
                    left: None,
                    right: None,
                    data: Some(val),
                })),
                None => None,
            };
            leaves.push(leaf);
        }
        while leaves.len() > 1 {
            let mut parents: Vec<Option<Box<Node<T>>>> = Vec::new();
            for i in (0..leaves.len()).step_by(2) {
                let left = leaves[i].take();
                let right = if i + 1 < leaves.len() {
                    leaves[i + 1].take()
                } else {
                    None
                };
                let parent_hash = match (&left, &right) {
                    (Some(l), Some(r)) => hash_func(&[l.hash, r.hash].concat()),
                    (Some(l), None) => l.hash,
                    (None, Some(r)) => r.hash,
                    (None, None) => [0; 32],
                };
                let parent = Some(Box::new(Node {
                    hash: parent_hash,
                    left,
                    right,
                    data: None,
                }));
                parents.push(parent);
            }
            leaves = parents;
        }
        let root = leaves.pop().unwrap_or(None);
        MerkleSparseTree { root }
    }

    fn get_root_hash(&self) -> [u8; 32] {
        match &self.root {
            Some(node) => node.hash,
            None => [0; 32],
        }
    }
}

fn main() {
    let pp: Vec<Option<u32>> = vec![Some(10), None, None, Some(20)];
    let map: HashMap<u32, [u8; 32]> = HashMap::new();
    let tree = MerkleSparseTree::new(pp.clone(), &|_data| [0; 32]);
    println!("{:?}", tree.get_root_hash());
}
