                // Update the position of the background tile based on the camera's position
                transform.translation.x = camera_offset.x;
                transform.translation.y = camera_offset.y;

                // Adjust the position based on the window size if needed
                transform.translation.x -= window.width() / 2.0;
                transform.translation.y -= window.height() / 2.0;
            }
        }
    }
}
