```rust
use std::collections::HashMap;

// Define a struct to represent a node in the Huffman tree
struct Node {
    character: Option<char>,
    frequency: usize,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

// Function to build a mapping of characters to their respective Huffman codes
pub fn gen_map_json(v: &str) -> String {
    // Step 1: Count the frequency of each character in the input string
    let mut frequency_map: HashMap<char, usize> = HashMap::new();
    for c in v.chars() {
        *frequency_map.entry(c).or_insert(0) += 1;
    }

    // Step 2: Build a priority queue of nodes based on the character frequencies
    let mut nodes: Vec<Box<Node>> = frequency_map
        .iter()
        .map(|(character, &frequency)| Box::new(Node {
            character: Some(*character),
            frequency,
            left: None,
            right: None,
        }))
        .collect();

    // Step 3: Build the Huffman tree by repeatedly combining the two lowest frequency nodes
    while nodes.len() > 1 {
        nodes.sort_by_key(|node| node.frequency);
        let left = nodes.remove(0);
        let right = nodes.remove(0);
        let combined_node = Box::new(Node {
            character: None,
            frequency: left.frequency + right.frequency,
            left: Some(left),
            right: Some(right),
        });
        nodes.push(combined_node);
    }

    // Step 4: Traverse the Huffman tree to generate the Huffman codes for each character
    let mut code_map: HashMap<char, String> = HashMap::new();
    if let Some(root) = nodes.pop() {
        let mut code = String::new();
        traverse_huffman_tree(&root, &mut code, &mut code_map);
    }

    // Step 5: Convert the code map to a JSON-formatted string
    serde_json::to_string(&code_map).unwrap()
}

// Function to traverse the Huffman tree and generate the Huffman codes
fn traverse_huffman_tree(node: &Node, code: &mut String, code_map: &mut HashMap<char, String>) {
    if let Some(character) = node.character {
        code_map.insert(character, code.clone());
    } else {
        if let Some(ref left) = node.left {
            code.push('0');
            traverse_huffman_tree(left, code, code_map);
            code.pop();
        }
        if let Some(ref right) = node.right {
            code.push('1');
            traverse_huffman_tree(right, code, code_map);
            code.pop();
        }
    }
}
```

In the solution, we first count the frequency of each character in the input string and then build a Huffman tree based on the character frequencies. We then traverse the Huffman tree to generate the Huffman codes for each character and finally convert the code map to a JSON-formatted string using the `serde_json` library.

