use std::path::PathBuf;
use url::Url;
use sha2::{Digest, Sha256};

pub fn url_to_filename(url: &Url) -> Option<PathBuf> {
    // Hash the URL using SHA-256
    let mut hasher = Sha256::new();
    hasher.update(url.as_str());
    let hash_result = hasher.finalize();

    // Convert the hashed result to a valid ASCII string for the filename
    let hashed_filename: String = hash_result.iter().map(|byte| format!("{:02x}", byte)).collect();

    // Replace characters that are not allowed in filenames with a safe character, e.g., '_'
