 / ___|| |_ __ _ _ __ | |__ (_)
 \\___ \\| __/ _` | '_ \\| '_ \\| |
  ___) | || (_| | | | | | | | |
 |____/ \\__\\__,_|_| |_|_| |_|_|
";

let modified_art = modify_ascii_art(original_ascii_art, "colorize", "Shopify:green");
// modified_art should be:
