//   ___) | || (_| | | | | | | | |
//  |____/ \\__\\__,_|_| |_|_| |_|_|
// "
```

```rust
fn modify_ascii_art(ascii_art: &str, operation: &str, params: &str) -> String {
    let mut modified_art = String::new();

    match operation {
        "colorize" => {
            let parts: Vec<&str> = params.split(':').collect();
            let word_to_colorize = parts[0];
            let color = parts[1];

            for line in ascii_art.lines() {
                if line.contains(word_to_colorize) {
                    let colored_word = format!("\x1b[{}m{}\x1b[0m", color, word_to_colorize);
                    let modified_line = line.replace(word_to_colorize, &colored_word);
                    modified_art.push_str(&modified_line);
                } else {
                    modified_art.push_str(line);
                }
                modified_art.push('\n');
            }
        }
        "replace" => {
            let parts: Vec<&str> = params.split(':').collect();
            let word_to_replace = parts[0];
            let new_word = parts[1];

            for line in ascii_art.lines() {
                let modified_line = line.replace(word_to_replace, new_word);
                modified_art.push_str(&modified_line);
                modified_art.push('\n');
            }
        }
        _ => {
            modified_art.push_str(ascii_art);
        }
    }

    modified_art
}
```

