use warp::Filter;

pub struct Api {
    listen_address: String,
    launcher_tx: Box<dyn LauncherTx>,
}

impl Api {
    pub async fn run(self) {
        let routes = self.routes();
        warp::serve(routes).run(self.listen_address.parse().unwrap()).await;
    }

    fn routes(self) -> impl Filter<Extract = impl warp::Reply, Error = warp::Rejection> + Clone {
        let launcher_tx = self.launcher_tx.clone();
        let api = warp::any().map(move || Api { listen_address: self.listen_address.clone(), launcher_tx: launcher_tx.clone() });

        let hello = warp::path!("hello" / String)
            .map(|name| format!("Hello, {}!", name));

        let launch = warp::path("launch")
            .and(warp::post())
            .and(warp::body::json())
            .and(api.clone())
            .and_then(|body: LaunchRequest, api: Api| async move {
                // Handle launch request using launcher_tx
                let response = api.launcher_tx.launch(body).await;
                match response {
                    Ok(result) => Ok(warp::reply::json(&result)),
                    Err(err) => Err(warp::reject::custom(ApiError::LaunchFailed(err))),
                }
            });

        hello.or(launch)
    }
}
