fn affine_encrypt(plaintext: &str, a: i32, b: i32) -> String {
    let ciphertext: String = plaintext
        .chars()
        .filter(|&c| c.is_ascii_alphabetic())
        .map(|c| {
            let x = (c as i32 - 65);
            (((a * x + b) % 26 + 26) % 26 + 65) as u8 as char
        })
        .collect();
    ciphertext
}

fn affine_decrypt(ciphertext: &str, a: i32, b: i32) -> String {
    let a_inv = modular_inverse(a).expect("Invalid key: a has no modular inverse");
    let plaintext: String = ciphertext
        .chars()
        .filter(|&c| c.is_ascii_alphabetic())
        .map(|c| {
            let x = (c as i32 - 65);
            (((a_inv * (x - b + 26) % 26 + 26) % 26) + 65) as u8 as char
        })
        .collect();
    plaintext
}

