    let mut width: Option<u64> = None;

    let mut iter = tokens.iter().peekable();
    while let Some(token) = iter.next() {
        if let Token::Str(key) = token {
            if let Some(Token::Some) = iter.next() {
                if let Some(Token::Str(value)) = iter.next() {
                    match key.as_str() {
                        "proxy_url" => proxy_url = Some(value.clone()),
                        "width" => {
                            if let Ok(w) = value.parse() {
                                width = Some(w);
                            } else {
                                return None; // Invalid width value
                            }
                        }
                        _ => {} // Ignore other keys
                    }
                } else {
                    return None; // Missing value after Some token
                }
            } else {
                return None; // Missing Some token after key
            }
        }
    }

    if let (Some(proxy), Some(w)) = (proxy_url, width) {
        Some((proxy, w))
    } else {
        None
    }
}
