struct TimeseriesWriter {
    file: File,
    buffer_size: usize,
    start_time: SystemTime,
    interval: Duration,
    buffer: Vec<(SystemTime, f64)>,
}

impl TimeseriesWriter {
    fn create(file: File, buffer_size: usize, start_time: SystemTime, interval: Duration) -> Result<Self> {
        Ok(TimeseriesWriter {
            file,
            buffer_size,
            start_time,
            interval,
            buffer: Vec::with_capacity(buffer_size),
        })
    }

    fn write_data_point(&mut self, timestamp: SystemTime, value: f64) -> Result<()> {
        self.buffer.push((timestamp, value));
        if self.buffer.len() >= self.buffer_size {
            self.flush()?;
        }
        Ok(())
    }

    fn flush(&mut self) -> Result<()> {
        for (timestamp, value) in &self.buffer {
            let formatted_timestamp = timestamp.duration_since(self.start_time)?.as_secs_f64();
            writeln!(&self.file, "{},{}", formatted_timestamp, value)?;
        }
        self.buffer.clear();
        Ok(())
    }
}

