struct BitManipulator(u128);

impl BitManipulator {
    #[inline]
    fn change(&mut self, b: usize, x: bool) {
        *self = (*self & !(1 << b)) | ((x as u128) << b);
    }

    #[inline]
    fn check(self, b: usize) -> bool {
        self >> b & 1 == 1
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_bit_manipulator() {
        let mut bit_manipulator = BitManipulator(0b1010);
        assert_eq!(bit_manipulator.check(0), false);
        assert_eq!(bit_manipulator.check(1), true);
        bit_manipulator.change(0, true);
        assert_eq!(bit_manipulator.check(0), true);
        assert_eq!(bit_manipulator.check(1), true);
        bit_manipulator.change(1, false);
        assert_eq!(bit_manipulator.check(0), true);
        assert_eq!(bit_manipulator.check(1), false);
    }
}
```

The `BitManipulator` struct is implemented with the `change` and `check` methods. The `change` method modifies the data structure by setting the bit at index `b` to the value of `x`, and the `check` method returns the value of the bit at index `b`. The provided test cases ensure the correctness of the implementation.

