use std::borrow::Cow;

pub struct Context;

pub struct ProgramBuilder<'a, T: ProgramBuilderType> {
    ctx: &'a Context,
    ty: T,
    sources: Vec<&'a [u8]>,
    opts: Option<Cow<'a, str>>,
}

pub trait ProgramBuilderType {}

pub struct FromSource<'a> {
    sources: Vec<&'a [u8]>,
}

impl<'a> ProgramBuilderType for FromSource<'a> {}

impl<'a> ProgramBuilder<'a, FromSource<'a>> {
    pub fn with_source(ctx: &'a Context, src: &'a impl AsRef<[u8]>) -> Self {
        Self {
            ctx,
            ty: FromSource { sources: vec![src.as_ref()] },
            sources: vec![src.as_ref()],
            opts: None,
        }
    }

    pub fn with_sources(mut self, srcs: Vec<&'a [u8]>) -> Self {
        self.ty = FromSource { sources: srcs.clone() };
        self.sources = srcs;
        self
    }

    pub fn with_options(mut self, opts: &'a str) -> Self {
        self.opts = Some(Cow::Borrowed(opts));
        self
    }
}

fn main() {
    let ctx = Context;
    let src1: &[u8] = b"source1";
    let src2: &[u8] = b"source2";
    let src3: &[u8] = b"source3";

    let program = ProgramBuilder::with_source(&ctx, src1)
        .with_sources(vec![src2, src3])
        .with_options("-O3")
        .with_options("-Wall")
        .with_options("-std=c++11");
}
```

In this solution, the `ProgramBuilder` struct is extended to support multiple source files and options. The `with_sources` method allows adding multiple source files, and the `with_options` method enables setting options for the program. The program builder is designed to be ergonomic and flexible, allowing for easy construction of programs with various combinations of source files and options.

