fn find_earliest_bus_time(schedule: &[(String, u32, u32)], current_time: u32) -> u32 {
    let mut earliest_time = u32::max_value();
    for (route, start_time, frequency) in schedule {
        let start_minutes = parse_time(start_time);
        let mut next_time = start_minutes;
        while next_time < current_time {
            next_time += frequency;
        }
        if next_time < earliest_time {
            earliest_time = next_time;
        }
    }
    earliest_time
}

