#[derive(Debug, PartialEq)]
enum PixelState {
    On,
    Off,
}

struct Document {
    width: usize,
    height: usize,
    pixels: Vec<PixelState>,
}

impl Document {
    fn new(width: usize, height: usize) -> Self {
        Document {
            width,
            height,
            pixels: vec![PixelState::Off; width * height],
        }
    }

    fn set_pixel(&mut self, x: usize, y: usize, state: PixelState) {
        if x < self.width && y < self.height {
            let index = y * self.width + x;
            self.pixels[index] = state;
        }
    }

    fn get_pixel(&self, x: usize, y: usize) -> Option<&PixelState> {
        if x < self.width && y < self.height {
            let index = y * self.width + x;
            Some(&self.pixels[index])
        } else {
            None
        }
    }

    fn count_on_pixels(&self) -> usize {
        self.pixels.iter().filter(|&p| *p == PixelState::On).count()
    }

    fn pixels(&self) -> &[PixelState] {
        &self.pixels
    }
}

fn main() {
