use std::env;

fn expand_home_dir(command: Command) -> Command {
    match command {
        Command::Simple { mut words, redirects } => {
            for word in &mut words {
                if word.starts_with("~") {
                    if let Some(home_dir) = env::var("HOME").ok() {
                        *word = word.replace("~", &home_dir);
                    }
                }
            }
            Command::Simple { words, redirects }
        }
        Command::Complex { mut words, redirects, conditionals } => {
            for word in &mut words {
                if word.starts_with("~") {
                    if let Some(home_dir) = env::var("HOME").ok() {
                        *word = word.replace("~", &home_dir);
                    }
                }
            }
            Command::Complex { words, redirects, conditionals }
        }
    }
}
```

