    let width = (cols * square_size) + 20;
    let height = (rows * square_size) + 20;

    let mut doc = Document::new()
        .set("viewBox", (0, 0, width, height))
        .add(Rect::new().set("width", width).set("height", height).set("fill", "none").set("stroke", "black"));

