```rust
fn hamming_distance(sequence_1: &str, sequence_2: &str) -> Result<usize, String> {
    if sequence_1.len() != sequence_2.len() {
        return Err(String::from("Sequences have different lengths"));
    }

    let distance = sequence_1.chars()
        .zip(sequence_2.chars())
        .filter(|(c1, c2)| c1 != c2)
        .count();

    Ok(distance)
}
