fn count_block_ids(func: &Function) -> Vec<(BlockId, i32)> {
    let mut counts = vec![(BlockId::NONE, 0)]; // Initialize counts with BlockId::NONE

    for param in &func.params {
        if let Some((bid, _)) = param.default_value {
            // Check if the block ID is already in the counts vector
            if let Some((index, count)) = counts.iter_mut().find(|(id, _)| *id == bid) {
                *count += 1; // Increment the count for the existing block ID
            } else {
                counts.push((bid, 1)); // Add the block ID with count 1 to the counts vector
            }
        }
    }

    counts
}
