use reqwest::blocking::Client;
use reqwest::blocking::RequestBuilder as ReqwestRequestBuilder;
use reqwest::blocking::Response;
use reqwest::Url;

pub struct RequestBuilder {
    method: http::Method,
    url: Url,
    headers: reqwest::header::HeaderMap,
    body: Option<Vec<u8>>,
}

impl RequestBuilder {
    pub fn new(method: http::Method, url: Url) -> Self {
        RequestBuilder {
            method,
            url,
            headers: reqwest::header::HeaderMap::new(),
            body: None,
        }
    }

    pub fn header(mut self, name: &str, value: &str) -> Self {
        self.headers.insert(name, reqwest::header::HeaderValue::from_str(value).unwrap());
        self
    }

    pub fn body(mut self, body: Vec<u8>) -> Self {
        self.body = Some(body);
        self
    }

    pub fn send(self) -> Result<Response, reqwest::Error> {
        let client = Client::new();
        let mut request = client.request(self.method, self.url);
        for (name, value) in self.headers.iter() {
            request = request.header(name, value);
        }
        if let Some(body) = self.body {
            request = request.body(body);
        }
        request.send()
    }
}
```

