    pub async fn run(mut self) {
        let mut sender = self.sender.clone();
        let message = Message {
            content: String::from("Hello, World!"),
        };
        sender.send(message).await.expect("Failed to send message");
    }

    pub async fn start() {
        let (sender, receiver) = mpsc::channel(100);
        let system = MessagePassingSystem { sender, receiver };
        let task = task::spawn(async move {
            system.run().await;
        });
        task.await.expect("Failed to run the task");
    }

    pub async fn receive_message(mut self) {
        while let Some(message) = self.receiver.recv().await {
            println!("Received message: {}", message.content);
        }
    }
}

#[tokio::main]
async fn main() {
    let system = MessagePassingSystem::start();
    system.receive_message().await;
}
