impl Exports {
    fn add(&mut self, new_export: &Export, c: Export) -> Option<Export> {
        if let Some(existing_export) = self.get_export_by_name(new_export.name) {
            Some(existing_export)
        } else {
            self.add_export(new_export, c);
            None
        }
    }

