}

impl MemoryManager {
    fn new(num_pages: usize) -> MemoryManager {
        MemoryManager {
            allocated_page_map: vec![false; num_pages],
        }
    }

    fn allocate_page(&mut self) -> Option<usize> {
        if let Some(index) = self.allocated_page_map.iter().position(|&x| !x) {
            self.allocated_page_map[index] = true;
            Some(index)
        } else {
            None
        }
    }

    fn deallocate_page(&mut self, index: usize) -> bool {
        if index < self.allocated_page_map.len() && self.allocated_page_map[index] {
            self.allocated_page_map[index] = false;
            true
        } else {
            false
        }
    }
}

fn main() {
    let mut memory_manager = MemoryManager::new(10);
    println!("{:?}", memory_manager.allocate_page()); // Some(0)
    println!("{:?}", memory_manager.allocate_page()); // Some(1)
    println!("{:?}", memory_manager.deallocate_page(0)); // true
    println!("{:?}", memory_manager.deallocate_page(0)); // false
}
```

