use std::pin::Pin;
use std::task::{Context, Poll};
use tokio::io::{AsyncRead, ReadBuf};

pub struct TakeUntil<R> {
    reader: R,
    delim: u8,
    buffer: Vec<u8>,
    done: bool,
}

impl<R: AsyncRead + Unpin> TakeUntil<R> {
    pub fn new(reader: R, delim: u8) -> Self {
        TakeUntil {
            reader,
            delim,
            buffer: Vec::new(),
            done: false,
        }
    }
}

impl<R: AsyncRead + Unpin> AsyncRead for TakeUntil<R> {
    fn poll_read(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &mut ReadBuf<'_>,
    ) -> Poll<std::io::Result<()>> {
        if self.done {
            return Poll::Ready(Ok(()));
        }

        let mut read_buf = [0; 1024];
        match Pin::new(&mut self.reader).poll_read(cx, &mut read_buf) {
            Poll::Ready(Ok(n)) => {
                if let Some(index) = read_buf.iter().position(|&x| x == self.delim) {
                    self.buffer.extend_from_slice(&read_buf[..index + 1]);
                    self.done = true;
                } else {
                    self.buffer.extend_from_slice(&read_buf[..n]);
                }
                buf.put_slice(&self.buffer);
                Poll::Ready(Ok(()))
            }
            Poll::Ready(Err(e)) => Poll::Ready(Err(e)),
            Poll::Pending => Poll::Pending,
        }
    }
}
```

This solution defines a `TakeUntil` struct that wraps the original reader and implements the `AsyncRead` trait for it. The `poll_read` method is used to read from the wrapped reader until the specified delimiter is encountered, and then stop reading. The bytes read until the delimiter is encountered are stored in the buffer and returned to the caller.

