use robin_core::ast::{BooleanExpression, Expression};
use robin_core::table::Table;

fn evaluate_boolean_expression(expression: &BooleanExpression, table: &Table) -> bool {
    match expression {
        BooleanExpression::Variable(var_name) => {
            if let Some(var_expr) = table.get(var_name) {
                if let Expression::Boolean(bool_expr) = var_expr {
                    return evaluate_boolean_expression(bool_expr, table);
                }
            }
            panic!("Variable {} not found in table", var_name);
        }
        BooleanExpression::Literal(value) => *value,
        BooleanExpression::And(left, right) => {
            evaluate_boolean_expression(left, table) && evaluate_boolean_expression(right, table)
        }
        BooleanExpression::Or(left, right) => {
            evaluate_boolean_expression(left, table) || evaluate_boolean_expression(right, table)
        }
        BooleanExpression::Not(expr) => !evaluate_boolean_expression(expr, table),
    }
}
```
This solution provides a recursive implementation of the `evaluate_boolean_expression` function. It matches the given boolean expression AST and evaluates it based on the variable bindings from the table. If a variable is encountered, it looks up the variable's value in the table and recursively evaluates the associated boolean expression. The logical operators `And`, `Or`, and `Not` are evaluated based on the results of their sub-expressions. If a variable is not found in the table, the function panics with an error message.

