// Define the custom error type AppError
#[derive(Debug)]
enum AppError {
    PwmError,
    UartError,
    Unknown,
}

// Define the hardware-specific errors
#[derive(Debug)]
struct PwmConfigurationError;
#[derive(Debug)]
struct UartConfigError;

// Implement the From trait for converting PwmConfigurationError to AppError
impl From<PwmConfigurationError> for AppError {
    fn from(_err: PwmConfigurationError) -> Self {
        AppError::PwmError
    }
}

// Implement the From trait for converting UartConfigError to AppError
impl From<UartConfigError> for AppError {
    fn from(_err: UartConfigError) -> Self {
        AppError::UartError
    }
}

// Function to handle hardware errors and convert them to AppError
fn handle_hardware_error<T>(result: Result<(), T>) -> AppError
where
    T: std::fmt::Debug,
{
    match result {
        Err(err) => {
            if let Some(_err) = err.downcast_ref::<PwmConfigurationError>() {
                AppError::from(_err)
            } else if let Some(_err) = err.downcast_ref::<UartConfigError>() {
                AppError::from(_err)
            } else {
                AppError::Unknown
            }
        }
        Ok(()) => AppError::Unknown,
    }
}

fn main() {
    // Example usage of handle_hardware_error function
    let pwm_error: Result<(), Box<dyn std::error::Error>> = Err(Box::new(PwmConfigurationError));
    let uart_error: Result<(), Box<dyn std::error::Error>> = Err(Box::new(UartConfigError));
    let unknown_error: Result<(), Box<dyn std::error::Error>> = Err(Box::new(std::io::Error::new(std::io::ErrorKind::Other, "Unknown error")));

    println!("{:?}", handle_hardware_error(pwm_error)); // Output: PwmError
    println!("{:?}", handle_hardware_error(uart_error)); // Output: UartError
    println!("{:?}", handle_hardware_error(unknown_error)); // Output: Unknown
}
