fn convert_pixels_to_rgb(pixel_data: &[u8], pal_mem: &[u16]) -> Vec<(u8, u8, u8)> {
    let mut rgb_pixels = Vec::new();
    for &pixel_value in pixel_data {
        let palette_index = pixel_value as usize;
        if palette_index < pal_mem.len() {
            let color = pal_mem[palette_index];
            let r = ((color >> 8) & 0xF8) as u8;
            let g = ((color >> 3) & 0xF8) as u8;
            let b = ((color << 3) & 0xF8) as u8;
            rgb_pixels.push((r, g, b));
        } else {
            // Handle out-of-bounds palette index
            rgb_pixels.push((0, 0, 0)); // Default to black color
        }
    }
    rgb_pixels
}

fn main() {
    let pixel_data = vec![0, 1, 2, 3];
    let pal_mem = vec![0x1234, 0x5678, 0x9abc, 0xdef0];
    let rgb_pixels = convert_pixels_to_rgb(&pixel_data, &pal_mem);
    println!("{:?}", rgb_pixels); // Output: [(18, 52, 86), (87, 154, 188), (222, 240, 0)]
}
```

