            let clipboard_locked_data = GlobalLockedData::lock(clipboard_data)?;

            let num_files = DragQueryFileW(clipboard_locked_data.as_ptr(), 0xFFFFFFFF, std::ptr::null_mut(), 0);
            if num_files == 0 {
                return Err(io::Error::new(io::ErrorKind::Other, "Clipboard does not contain files"));
            }

            let mut file_paths = Vec::with_capacity(num_files as usize);
            for i in 0..num_files {
                let mut file_path_buffer = vec![0u16; 260]; // Max path length
                let chars_copied = DragQueryFileW(clipboard_locked_data.as_ptr(), i, file_path_buffer.as_mut_ptr(), file_path_buffer.len() as u32);
                if chars_copied > 0 {
                    let file_path = PathBuf::from(String::from_utf16_lossy(&file_path_buffer[..chars_copied as usize]));
                    file_paths.push(file_path);
                }
            }

            Ok(file_paths)
        }
    }
}
```

