// Implement the InterruptHandler trait with a handle method
trait InterruptHandler {
    fn handle(&self);
}

// Implement the add_interrupt method for the interrupt handling module
struct InterruptHandlerModule<I: InterruptHandler> {
    interrupts: Vec<Interruptable<'static, I>>,
}

impl<I: InterruptHandler> InterruptHandlerModule<I> {
    fn add_interrupt(&mut self, interrupt: &'static I, irq: u8) {
        if self.interrupts.len() < u8::MAX as usize {
            self.interrupts
                .push(Interruptable::new(interrupt, irq));
        } else {
            panic!("too many interrupts");
        }
    }

    fn on_interrupt(&self, irqn: i16) {
        log::trace!("IRQ: {}", irqn);
        for interrupt in self.interrupts.iter().filter(|e| e.irq == irqn as u8) {
            interrupt.interrupt.handle();
        }
    }
}
