use std::io;
use std::io::prelude::*;

fn p1(buf: &mut dyn BufRead) -> Result<Vec<i32>, io::Error> {
    let mut numbers = String::new();
    buf.read_to_string(&mut numbers)?;

    let result: Vec<i32> = numbers
        .split_whitespace()
        .map(|s| s.parse().expect("Invalid integer"))
        .collect();

    Ok(result)
}

fn p2(buf: &mut dyn BufRead) -> Result<i32, io::Error> {
    let mut sum = 0;
    let mut count = 0;

    for line in buf.lines() {
        let num: i32 = line?.trim().parse().expect("Invalid integer");
        sum += num;
        count += 1;
    }

    Ok(sum / count)
}
