```rust
use mongodb::{Client, Database, bson::doc};
use std::error::Error;

pub struct Db;

impl TypeMapKey for Db {
    type Value = Database;
}

pub async fn init_db() -> Result<Database, Box<dyn Error>> {
    let client = Client::with_uri_str("mongodb://localhost:27017/").await?;
    let db = client.database("ornery-bot");
    Ok(db)
}

pub async fn insert_message(db: &Database, message: &str) -> Result<(), Box<dyn Error>> {
    let collection = db.collection("messages");
    collection.insert_one(doc! { "message": message }, None).await?;
    Ok(())
}

pub async fn get_messages(db: &Database) -> Result<Vec<String>, Box<dyn Error>> {
    let collection = db.collection("messages");
    let cursor = collection.find(None, None).await?;
    let mut messages = Vec::new();
    for result in cursor {
        let document = result?;
        if let Some(message) = document.get_str("message") {
            messages.push(message.to_string());
        }
    }
    Ok(messages)
}

pub async fn update_message(db: &Database, old_message: &str, new_message: &str) -> Result<(), Box<dyn Error>> {
