fn get_most_common(arr: &Vec<i32>) -> i32 {
    if arr.is_empty() {
        return -1; // Return -1 for an empty array
    }

    let ones_count = arr.iter().filter(|&i| *i == 1).count();
    let zeroes_count = arr.len() - ones_count;

    if ones_count == zeroes_count {
        return 0; // Return 0 if the counts are equal
    } else if ones_count > zeroes_count {
        return 1; // Return 1 if ones are more than zeroes
    } else {
        return 0; // Return 0 if zeroes are more than ones
    }
}

fn main() {
    let arr = vec![0, 1, 1, 0, 1, 0, 0, 1, 1];
    println!("{}", get_most_common(&arr)); // Output: 1
}
