struct Riot {
    timer_value: u8,
    timer_reset: bool,
    timer_interrupt: bool,
}

impl Riot {
    fn set(&mut self, value: u8) {
        self.timer_value = value;
    }

    fn tick(&mut self, decrement_amount: u8) {
        if self.timer_value > 0 {
            self.timer_value = self.timer_value.saturating_sub(decrement_amount);
            if self.timer_value == 0 {
                self.timer_interrupt = true;
                self.timer_reset = true;
            }
        }
    }

    fn get(&self) -> u8 {
        self.timer_value
    }
}
