fn process_packets<I, T>(mut packets: I) -> HashMap<T, Vec<Signature>>
where
    I: Iterator<Item = Packet<T>>,
    T: Eq + std::hash::Hash,
{
    let mut subkey_signatures_map: HashMap<T, Vec<Signature>> = HashMap::new();

    while let Some(packet) = packets.next() {
        match packet.tag() {
            Tag::SubkeyTag1 => {
                let subkey: $inner_subkey_type = err_opt!(packet.try_into());
                let mut sigs = Vec::new();
                while let Some(true) = packets.peek().map(|packet| packet.tag() == Tag::Signature) {
                    let packet = packets.next().expect("peeked");
                    let sig: Signature = err_opt!(packet.try_into());
                    sigs.push(sig);
                }
                subkey_signatures_map.insert(subkey, sigs);
            }
            Tag::SubkeyTag2 => {
                // Handle SubkeyTag2 processing similarly if needed
            }
            _ => {
                // Handle other tag variants if needed
            }
        }
    }

    subkey_signatures_map
}
