fn schedule_tasks(tasks: Vec<Task>) -> Vec<String> {
    let mut immediate_tasks: Vec<&Task> = Vec::new();
    let mut delayed_tasks: Vec<&Task> = Vec::new();

    for task in &tasks {
        if task.can_start_here {
            immediate_tasks.push(task);
        } else {
            delayed_tasks.push(task);
        }
    }

    immediate_tasks.sort_by_key(|&task| task.service_time);

    let mut scheduled_tasks: Vec<String> = immediate_tasks.iter().map(|task| task.name.clone()).collect();

    let mut time_elapsed = immediate_tasks.iter().map(|task| task.service_time).sum::<u32>();

    delayed_tasks.sort_by_key(|&task| task.visit);

    for task in delayed_tasks {
        for _ in 0..task.visit {
            scheduled_tasks.push(task.name.clone());
            time_elapsed += task.service_time;
        }
    }

    scheduled_tasks
}
```

