use std::sync::{Arc, Mutex, MutexGuard};

struct PoolError;

struct MutexObjectPool<T> {
    objects: Vec<T>,
    initializer: Arc<dyn Fn() -> T>,
    cleaner: Arc<dyn Fn(T)>,
    mutex: Mutex<()>,
}

impl<T> MutexObjectPool<T> {
    fn new(initializer: impl Fn() -> T + 'static, cleaner: impl Fn(T) + 'static) -> Self {
        MutexObjectPool {
            objects: Vec::new(),
            initializer: Arc::new(initializer),
            cleaner: Arc::new(cleaner),
            mutex: Mutex::new(()),
        }
    }

    fn acquire(&self) -> Result<MutexGuard<T>, PoolError> {
        let _lock = self.mutex.lock().map_err(|_| PoolError)?;
        if let Some(obj) = self.objects.pop() {
            Ok(MutexGuard::map(self.mutex.lock().unwrap(), |_| obj))
        } else {
            let new_obj = (self.initializer)();
            Ok(MutexGuard::map(self.mutex.lock().unwrap(), |_| new_obj))
        }
    }

    fn release(&self, obj: MutexGuard<T>) {
        let obj = MutexGuard::into_inner(obj);
        (self.cleaner)(obj);
        self.objects.push(obj);
    }
}

fn main() {
    let pool = MutexObjectPool::new(|| String::new(), |s| drop(s));
    let obj1 = pool.acquire().unwrap();
    let obj2 = pool.acquire().unwrap();
    pool.release(obj1);
    pool.release(obj2);
}
```

