use std::collections::HashMap;

fn modify_css(original_css: &str, rules: &HashMap<&str, &str>) -> String {
    let mut modified_css = String::new();

    let lines: Vec<&str> = original_css.split('\n').collect();

    for line in lines {
        let trimmed_line = line.trim();
        if trimmed_line.is_empty() {
            modified_css.push_str("\n");
            continue;
        }

        let mut parts = trimmed_line.split('{').map(str::trim);
        let selector = parts.next().unwrap();
        let properties = parts.next().unwrap().trim_end_matches('}');

        modified_css.push_str(selector);
        modified_css.push_str(" {\n");
        modified_css.push_str(properties);
        modified_css.push_str("\n");

        if let Some(new_properties) = rules.get(selector) {
            modified_css.push_str(new_properties);
            modified_css.push_str("\n");
        }

        modified_css.push_str("}\n");
    }

    modified_css
}

fn main() {
    let original_css = r#"a {
  color: blue;
}
b {
  color: red;
}"#;

    let rules: HashMap<&str, &str> = [
        ("a", "text-decoration: underline;"),
        ("b", "font-weight: bold;"),
    ].iter().cloned().collect();

    let modified_css = modify_css(original_css, &rules);
    println!("{}", modified_css);
}
