```rust
use std::ops::{Add, Sub, Mul};

#[derive(Debug, PartialEq)]
struct Vec3 {
    x: f64,
    y: f64,
    z: f64,
}

impl Vec3 {
    fn new(x: f64, y: f64, z: f64) -> Vec3 {
        Vec3 { x, y, z }
    }

    fn from_slice(slice: &[f64]) -> Vec3 {
        assert_eq!(slice.len(), 3);
        Vec3::new(slice[0], slice[1], slice[2])
    }

    fn add(&self, other: &Vec3) -> Vec3 {
        Vec3::new(self.x + other.x, self.y + other.y, self.z + other.z)
    }

    fn sub(&self, other: &Vec3) -> Vec3 {
        Vec3::new(self.x - other.x, self.y - other.y, self.z - other.z)
    }

    fn mul_scalar(&self, scalar: f64) -> Vec3 {
        Vec3::new(self.x * scalar, self.y * scalar, self.z * scalar)
    }

    fn dot(&self, other: &Vec3) -> f64 {
        self.x * other.x + self.y * other.y + self.z * other.z
    }

    fn cross(&self, other: &Vec3) -> Vec3 {
        Vec3::new(
            self.y * other.z - self.z * other.y,
            self.z * other.x - self.x * other.z,
            self.x * other.y - self.y * other.x,
        )
    }

    fn normalize(&self) -> Vec3 {
        let mag = (self.x * self.x + self.y * self.y + self.z * self.z).sqrt();
        Vec3::new(self.x / mag, self.y / mag, self.z / mag)
    }
}

fn main() {
    let v1 = Vec3::new(1.0, 2.0, 3.0);
    let v2 = Vec3::new(4.0, 5.0, 6.0);

    let v3 = v1.add(&v2);
    let v4 = v1.sub(&v2);
    let v5 = v1.mul_scalar(2.0);
    let dot_product = v1.dot(&v2);
    let cross_product = v1.cross(&v2);
    let normalized_v1 = v1.normalize();

    println!("{:?}", v3); // Output: Vec3 { x: 5.0, y: 7.0, z: 9.0 }
    println!("{:?}", v4); // Output: Vec3 { x: -3.0, y: -3.0, z: -3.0 }
    println!("{:?}", v5); // Output: Vec3 { x: 2.0, y: 4.0, z: 6.0 }
    println!("{}", dot_product); // Output: 32.0
    println!("{:?}", cross_product); // Output: Vec3 { x: -3.0, y: 6.0, z: -3.0 }
    println!("{:?}", normalized_v1); // Output: Vec3 { x: 0.2672612419124244, y: 0.5345224838248488, z: 0.8017837257372732 }
}
