```rust
pub struct Heap<T, F>
where
    T: Ord,
    F: Fn(&T, &T) -> bool,
{
    data: Vec<T>,
    compare: F,
}

impl<T, F> Heap<T, F>
where
    T: Ord,
    F: Fn(&T, &T) -> bool,
{
    fn new(compare: F) -> Self {
        Heap {
            data: Vec::new(),
            compare,
        }
    }

    fn push(&mut self, value: T) {
        self.data.push(value);
        self.bubble_up(self.data.len() - 1);
    }

    fn pop_max(&mut self) -> Option<T> {
        if self.data.is_empty() {
            return None;
        }
        self.data.swap(0, self.data.len() - 1);
        let max = self.data.pop();
        self.bubble_down(0);
        max
    }

    fn bubble_up(&mut self, mut index: usize) {
        while index > 0 {
            let parent = (index - 1) / 2;
            if (self.compare)(&self.data[index], &self.data[parent]) {
                self.data.swap(index, parent);
                index = parent;
            } else {
                break;
            }
        }
    }

    fn bubble_down(&mut self, mut index: usize) {
        let len = self.data.len();
        while index < len {
            let left = 2 * index + 1;
            let right = 2 * index + 2;
            let mut largest = index;

            if left < len && (self.compare)(&self.data[left], &self.data[largest]) {
                largest = left;
            }
            if right < len && (self.compare)(&self.data[right], &self.data[largest]) {
                largest = right;
            }

            if largest != index {
                self.data.swap(index, largest);
                index = largest;
            } else {
                break;
            }
        }
    }
}

pub struct MaxHeap<T: Ord>(Heap<T, fn(&T, &T) -> bool>);

impl<T: Ord> MaxHeap<T> {
    pub fn new() -> Self {
        MaxHeap(Heap::new(|a, b| a < b))
    }

    pub fn push(&mut self, value: T) {
        self.0.push(value);
    }

    pub fn pop_max(&mut self) -> Option<T> {
        self.0.pop_max()
    }
}
```

