fn check_eea<T: std::ops::Add<Output = T> + std::ops::Sub<Output = T> + std::ops::Mul<Output = T> + std::cmp::PartialEq + std::clone::Clone + std::marker::Copy>(a: T, b: T) -> bool
where
    T: std::cmp::PartialOrd + std::ops::Div<Output = T> + std::ops::Rem<Output = T> + std::ops::Neg<Output = T> + std::fmt::Debug,
{
    let (mut r0, mut r1, mut s0, mut s1, mut t0, mut t1) = (a, b, T::one(), T::zero(), T::zero(), T::one());
    while r1 != T::zero() {
        let q = r0 / r1;
        let temp = r1;
        r1 = r0 % r1;
        r0 = temp;
        let temp = s1;
        s1 = s0 - q * s1;
        s0 = temp;
        let temp = t1;
        t1 = t0 - q * t1;
        t0 = temp;
    }
    r0 == T::one()
}

fn main() {
    assert!(check_eea::<i32>(0, 0));
    assert!(check_eea::<i32>(42, 0));
    assert!(check_eea::<i32>(0, 42));
    assert!(check_eea::<i32>(64, 58));
    assert!(check_eea::<i32>(97, 89));
}
```
