fn even_fibonacci_sum(limit: u64) -> u64 {
    let (mut a, mut b) = (1, 2);
    let mut sum = 0;

    while b <= limit {
        if b % 2 == 0 {
            sum += b;
        }
        let next = a + b;
        a = b;
        b = next;
    }

    sum
}

fn main() {
    let limit = 10;
    println!("Sum of even Fibonacci numbers up to {}: {}", limit, even_fibonacci_sum(limit));
}
