use std::collections::HashMap;

#[derive(Debug, Clone)]
enum LispExpr {
    Atom(String),
    List(Vec<LispExpr>),
}

type Environment = HashMap<String, LispExpr>;

fn eval(expr: &LispExpr, env: &Environment) -> Result<(LispExpr, Environment), String> {
    match expr {
        LispExpr::Atom(val) => {
            if let Some(bind_val) = env.get(val) {
                Ok((bind_val.clone(), env.clone()))
            } else {
                Ok((LispExpr::Atom(val.clone()), env.clone()))
            }
        }
        LispExpr::List(list) => {
            if list.is_empty() {
                return Err("Empty list".to_string());
            }
            let first = &list[0];
            match first {
                LispExpr::Atom(func) if func == "if" => {
                    if list.len() != 4 {
                        return Err("Invalid if expression".to_string());
                    }
                    let test_expr = &list[1];
                    let conseq_expr = &list[2];
                    let alt_expr = &list[3];
                    let (test_val, _) = eval(test_expr, env)?;
                    match test_val {
                        LispExpr::Atom(_) => return Err("Invalid test expression".to_string()),
                        _ => {
                            let (result_expr, new_env) = if test_val == LispExpr::Atom("true".to_string()) {
                                eval(conseq_expr, env)?
                            } else {
                                eval(alt_expr, env)?
                            };
                            Ok((result_expr, new_env))
                        }
                    }
                }
                _ => Err("Unsupported function".to_string()),
            }
        }
    }
}

fn main() {
    let env: Environment = HashMap::new();
    let expr = LispExpr::List(vec![
        LispExpr::Atom("if".to_string()),
        LispExpr::Atom("true".to_string()),
        LispExpr::Atom("1".to_string()),
        LispExpr::Atom("2".to_string()),
    ]);
    match eval(&expr, &env) {
        Ok((result, _)) => println!("Result: {:?}", result),
        Err(err) => println!("Error: {}", err),
    }
}
```

