pub fn rotate270<C>(buffer: &PixelBuffer<C>) -> PixelBuffer<C> where C: Color {
    let mut result = vec![Default::default(); buffer.data().len()];

    for x in 0..buffer.width() {
        for y in 0..buffer.height() {
