```rust
pub fn rotate270<C>(buffer: &mut PixelBuffer<C>, width: usize, height: usize) where C: Color {
    let mut result = vec![Default::default(); buffer.data().len()];

    for x in 0..width {
        for y in 0..height {
            let x2 = height - y - 1;
            let y2 = x;
            result[(x2 + y2 * width) as usize] = buffer.data()[(x + y * width) as usize];
