```rust
mod core {
    use std::collections::{HashMap, HashSet};

    pub struct Module {
        name: String,
        dependencies: Vec<String>,
    }

    pub struct ModuleSystem {
        modules: HashMap<String, Module>,
    }

    impl ModuleSystem {
        pub fn new() -> ModuleSystem {
            ModuleSystem {
                modules: HashMap::new(),
            }
        }

        pub fn define_module(&mut self, name: &str, dependencies: Vec<&str>) {
            let module = Module {
                name: name.to_string(),
                dependencies: dependencies.iter().map(|&d| d.to_string()).collect(),
            };
            self.modules.insert(name.to_string(), module);
        }

        pub fn import_module(&self, name: &str) {
            let mut visited: HashSet<String> = HashSet::new();
            self.resolve_dependencies(name, &mut visited);
        }

        fn resolve_dependencies(&self, name: &str, visited: &mut HashSet<String>) {
            if visited.contains(name) {
                panic!("Circular dependency detected for module: {}", name);
            }
            visited.insert(name.to_string());

            if let Some(module) = self.modules.get(name) {
                for dependency in &module.dependencies {
                    self.resolve_dependencies(dependency, visited);
                }
            }
        }
    }
}
```

In this solution, the `Module` struct represents a module with its name and dependencies. The `ModuleSystem` struct maintains a collection of modules and provides methods to define and import modules. The `import_module` method triggers the resolution of dependencies for a given module, while the `resolve_dependencies` method recursively resolves the dependencies and detects circular dependencies using a `HashSet` to track visited modules. If a circular dependency is detected, the program panics with an error message.

