use std::sync::{Arc, Mutex};
use std::thread;

struct Delogger {
    messages: Arc<Mutex<Vec<String>>>,
    flush_threshold: usize,
}

impl Delogger {
    fn new(flush_threshold: usize) -> Delogger {
        Delogger {
            messages: Arc::new(Mutex::new(Vec::new())),
            flush_threshold,
        }
    }

    fn log(&self, msg: &str) {
        self.messages.lock().unwrap().push(msg.to_string());
        if self.messages.lock().unwrap().len() >= self.flush_threshold {
            self.flush();
        }
    }

    fn flush(&self) {
        let mut messages = self.messages.lock().unwrap();
        for msg in messages.iter() {
            println!("{}", msg);
        }
        messages.clear();
    }
}

fn main() {
    let delogger = Delogger::new(5);

    let handles: Vec<_> = (0..10)
        .map(|i| {
            let delogger_ref = delogger.clone();
            thread::spawn(move || {
                for j in 0..3 {
                    delogger_ref.log(&format!("Message from thread {}: {}", i, j));
                }
            })
        })
        .collect();

    for handle in handles {
        handle.join().unwrap();
    }

    delogger.flush();
}
```

In this solution, the `Delogger` struct is implemented to handle logging and flushing of messages. It uses a `Mutex` to ensure thread safety when accessing the log messages. The `log` method adds messages to the log and triggers a flush if the threshold is reached. The `flush` method prints and clears the log messages. In the `main` function, multiple threads are used to simulate concurrent logging, and the logs are flushed at the end.

